                ("CHM101", "Periodic table and periodicity", "Which of the following pairs violates the trend if arranged by atomic mass but is correct by atomic number?", "Na and Mg", "Ar and K", "Cl and S", "Ca and K", "B", "Explanation: Argon has higher mass than potassium but comes before it due to lower atomic number"),
                ("CHM101", "Periodic table and periodicity", "Which element has the largest atomic radius?", "Na", "Cl", "Mg", "Si", "A", "Explanation: Atomic radius decreases across a period from left to right"),
                ("CHM101", "Periodic table and periodicity", "Why does atomic radius decrease across a period?", "Decrease in electron shells", "Increase in nuclear charge", "Decrease in electrons", "Increase in shielding", "B", "Explanation: Greater nuclear charge pulls electrons closer"),
                ("CHM101", "Periodic table and periodicity", "Which element has the highest ionization energy?", "Na", "Mg", "Al", "Cl", "D", "Explanation: Ionization energy increases across a period; Cl is highest here"),
                ("CHM101", "Periodic table and periodicity", "Which of the following explains why ionization energy decreases down a group?", "Increased nuclear charge", "Increased shielding effect", "Decreased atomic size", "Increased electronegativity", "B", "Explanation: More inner shells reduce attraction between nucleus and valence electrons"),
                ("CHM101", "Periodic table and periodicity", "Which element has the highest electronegativity?", "Oxygen", "Fluorine", "Chlorine", "Nitrogen", "B", "Explanation: Fluorine is the most electronegative element"),
                ("CHM101", "Periodic table and periodicity", "Which element has the lowest electronegativity?", "Na", "Cl", "Mg", "Al", "A", "Explanation: Electronegativity increases across a period, so Na is lowest"),
                ("CHM101", "Periodic table and periodicity", "Electron affinity generally becomes more:", "Positive across a period", "Negative across a period", "Positive down a group", "Constant across a period", "B", "Explanation: Atoms gain electrons more easily across a period, releasing energy"),
                ("CHM101", "Periodic table and periodicity", "Which of the following has the most negative electron affinity?", "Na", "Cl", "Mg", "Ar", "B", "Explanation: Halogens like Cl strongly attract electrons"),
                ("CHM101", "Periodic table and periodicity", "Which element would require the least energy to remove an electron?", "K", "Ca", "Cl", "Ne", "A", "Explanation: Alkali metals have lowest ionization energy"),
                ("CHM101", "Periodic table and periodicity", "Why do noble gases have high ionization energies?", "They have large atomic radii", "They are highly reactive", "They have complete valence shells", "They have low nuclear charge", "C", "Explanation: Stable electron configuration makes electron removal difficult"),
                ("CHM101", "Periodic table and periodicity", "Which trend is correct down a group?", "Atomic radius decreases", "Ionization energy increases", "Electronegativity decreases", "Electron affinity increases", "C", "Explanation: Electronegativity decreases as atomic size increases"),
                ("CHM101", "Periodic table and periodicity", "Which of the following is NOT a periodic property?", "Atomic radius", "Ionization energy", "Density", "Electronegativity", "C", "Explanation: Density does not follow a clear periodic trend"),
                ("CHM101", "Periodic table and periodicity", "Which element has the smallest atomic radius?", "Na", "Cl", "Mg", "Al", "B", "Explanation: Atomic size decreases across the period; Cl is smallest"),
                ("CHM101", "Periodic table and periodicity", "Why is fluorine more electronegative than chlorine?", "Smaller atomic size", "Higher atomic mass", "More electron shells", "Lower nuclear charge", "A", "Explanation: Smaller size means stronger attraction for electrons"),
                ("CHM101", "Periodic table and periodicity", "Which element shows an exception in ionization energy trend?", "Be", "B", "C", "N", "B", "Explanation: Boron has lower ionization energy than expected due to electron entering p orbital"),
                ("CHM101", "Periodic table and periodicity", "Which element has the highest ionization energy in Group 1?", "Li", "Na", "K", "Rb", "A", "Explanation: Ionization energy decreases down the group, so Li is highest"),
                ("CHM101", "Periodic table and periodicity", "Which of the following statements is FALSE?", "Atomic radius increases down a group", "Ionization energy decreases down a group", "Electronegativity increases down a group", "Electron affinity becomes less negative down a group", "C", "Explanation: Electronegativity actually decreases down a group"),

                #Chemical bonding
                ("CHM101", "Chemical Bonding", "Which of the following compounds is most ionic in character?", "NaCl", "HCl", "CO2", "CH4", "A", "Explanation: Ionic character increases with electronegativity difference; NaCl has the largest difference"),
                ("CHM101", "Chemical bonding", "Which type of bonding involves complete transfer of electrons?", "Covalent bonding", "Metallic bonding", "Ionic bonding", "Hydrogen bonding", "C", "Explanation: Ionic bonding occurs via transfer of electrons from one atom to another"),
                ("CHM101", "Chemical bonding", "Which of the following molecules is nonpolar despite having polar bonds?", "H2O", "NH3", "CO2", "SO2", "C", "Explanation: CO2 is linear, so dipoles cancel out"),
                ("CHM101", "Chemical bonding", "Which hybridization corresponds to a linear molecular geometry?", "sp", "sp²", "sp³", "sp³d", "A", "Explanation: sp hybridization gives 180° linear shape"),
                ("CHM101", "Chemical bonding", "The bond angle in an sp² hybridized molecule is approximately:", "90°", "109.5°", "120°", "180°", "C", "Explanation: sp² hybridization leads to trigonal planar geometry with 120° angles"),
                ("CHM101", "Chemical bonding", "Which of the following molecules has tetrahedral geometry?", "CO2", "BF3", "CH4", "NH3", "C", "Explanation: CH4 is sp³ hybridized with tetrahedral shape"),
                ("CHM101", "Chemical bonding", "Which of the following best explains metallic bonding?", "Sharing of electrons between atoms", "Transfer of electrons between atoms", "Sea of delocalized electrons", "Attraction between dipoles", "C", "Explanation: Metallic bonding involves delocalized electrons moving freely"),
                ("CHM101", "Chemical bonding", "Which molecule has a lone pair that affects its shape?", "CO2", "CH4", "NH3", "BF3", "C", "Explanation: NH3 has one lone pair, giving trigonal pyramidal shape"),
                ("CHM101", "Chemical bonding", "Which of the following has trigonal planar geometry?", "NH3", "CH4", "BF3", "H2O", "C", "Explanation: BF3 is sp² hybridized with no lone pairs"),
                ("CHM101", "Chemical bonding", "Which type of bond is formed by overlap of orbitals?", "Ionic bond", "Covalent bond", "Metallic bond", "Hydrogen bond", "B", "Explanation: Covalent bonding involves orbital overlap"),
                ("CHM101", "Chemical bonding", "Which of the following molecules is bent in shape?", "CO2", "BF3", "H2O", "CH4", "C", "Explanation: H2O has two lone pairs causing bent geometry"),
                ("CHM101", "Chemical bonding", "Which hybridization is present in methane (CH4)?", "sp", "sp²", "sp³", "sp³d", "C", "Explanation: Carbon forms four sigma bonds → sp³ hybridization"),
                ("CHM101", "Chemical bonding", "Which molecule has bond angles closest to 109.5°?", "NH3", "H2O", "CH4", "CO2", "C", "Explanation: CH4 has ideal tetrahedral angle of 109.5°"),
                ("CHM101", "Chemical bonding", "Which of the following has the strongest covalent bond?", "Single bond", "Double bond", "Triple bond", "All equal", "C", "Explanation: Triple bonds have highest bond energy"),
                ("CHM101", "Chemical bonding", "Which statement about ionic compounds is correct?", "They have low melting points", "They conduct electricity in solid state", "They form crystalline solids", "They share electrons", "C", "Explanation: Ionic compounds form crystal lattices"),
                ("CHM101", "Chemical bonding", "Which molecule exhibits sp hybridization?", "CO2", "CH4", "NH3", "H2O", "A", "Explanation: CO2 has two regions of electron density → sp hybridization"),
                ("CHM101", "Chemical bonding", "Which factor determines molecular shape in VSEPR theory?", "Mass of atoms", "Number of neutrons", "Electron pair repulsion", "Type of bond only", "C", "Explanation: Shape is determined by repulsion between electron pairs"),
                ("CHM101", "Chemical bonding", "Which of the following molecules has trigonal pyramidal shape?", "BF3", "NH3", "CO2", "CH4", "B", "Explanation: NH3 has three bonds and one lone pair"),
                ("CHM101", "Chemical bonding", "Which compound has delocalized electrons responsible for conductivity?", "NaCl", "H2O", "Cu", "CO2", "C", "Explanation: Metals like Cu have free-moving electrons"),
                ("CHM101", "Chemical bonding", "Which statement about covalent bonds is FALSE?", "They involve sharing of electrons", "They form between nonmetals", "They always produce polar molecules", "They involve orbital overlap", "C", "Explanation: Covalent bonds can be polar or nonpolar depending on electronegativity difference"),

                #Intermolecular forces and structure of matter
                ("CHM101", "Intermolecular forces and structure of matter", "Which of the following intermolecular forces is the weakest?", "Hydrogen bonding", "Dipole-dipole interaction", "London dispersion forces", "Ionic bonding", "C", "Explanation: London dispersion forces are the weakest and arise from temporary dipoles"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which condition is necessary for hydrogen bonding?", "Hydrogen bonded to any atom", "Hydrogen bonded to F, O, or N", "Hydrogen bonded to metals", "Hydrogen bonded to carbon only", "B", "Explanation: Strong hydrogen bonding occurs when H is bonded to highly electronegative atoms like F, O, or N"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which molecule exhibits hydrogen bonding?", "CH4", "NH3", "CO2", "HCl", "B", "Explanation: NH3 has N-H bonds and lone pairs, enabling hydrogen bonding"),
                ("CHM101", "Intermolecular forces and structure of matter", "Why do noble gases have very low boiling points?", "Strong covalent bonding", "Strong hydrogen bonding", "Weak dispersion forces", "High polarity", "C", "Explanation: Noble gases only have weak London dispersion forces"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which substance has the strongest intermolecular forces?", "H2O", "CO2", "CH4", "O2", "A", "Explanation: Water exhibits strong hydrogen bonding"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which factor increases London dispersion forces?", "Low molecular mass", "Small surface area", "High polarizability", "Low number of electrons", "C", "Explanation: Larger, more polarizable electron clouds enhance dispersion forces"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which of the following has the highest boiling point?", "CH4", "NH3", "H2O", "HF", "C", "Explanation: H2O forms extensive hydrogen bonding networks"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which intermolecular force is present in all molecules?", "Hydrogen bonding", "Dipole-dipole", "London dispersion", "Ionic bonding", "C", "Explanation: All molecules exhibit London dispersion forces"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which of the following solids has the highest melting point?", "Molecular solid", "Ionic solid", "Metallic solid", "Covalent network solid", "D", "Explanation: Covalent network solids like diamond have very strong bonds"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which type of solid is characterized by a 'sea of electrons'?", "Ionic solid", "Molecular solid", "Metallic solid", "Covalent solid", "C", "Explanation: Metallic solids have delocalized electrons"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which of the following is an example of a molecular solid?", "NaCl", "CO2 (dry ice)", "Fe", "Diamond", "B", "Explanation: CO2 forms a molecular solid held by intermolecular forces"),
                ("CHM101", "Intermolecular forces and structure of matter", "Why is iodine (I2) solid at room temperature?", "Strong ionic bonds", "Hydrogen bonding", "Strong dispersion forces", "Covalent network bonding", "C", "Explanation: Large electron cloud increases dispersion forces"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which type of solid is brittle and conducts electricity when molten?", "Metallic", "Ionic", "Molecular", "Covalent network", "B", "Explanation: Ionic solids conduct when ions are free in molten state"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which molecule has dipole-dipole interactions but no hydrogen bonding?", "H2O", "NH3", "HCl", "HF", "C", "Explanation: HCl is polar but lacks H bonded to F, O, or N"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which of the following best explains surface tension in water?", "Ionic bonding", "Hydrogen bonding", "Dispersion forces", "Metallic bonding", "B", "Explanation: Strong hydrogen bonding gives water high surface tension"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which solid type has directional bonds and is very hard?", "Molecular solid", "Ionic solid", "Metallic solid", "Covalent network solid", "D", "Explanation: Covalent network solids like diamond have strong directional bonds"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which factor does NOT affect intermolecular forces?", "Molecular size", "Polarity", "Temperature", "Number of neutrons", "D", "Explanation: Neutrons do not influence intermolecular forces"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which of the following substances has only dispersion forces?", "NH3", "H2O", "CO2", "HF", "C", "Explanation: CO2 is nonpolar, so only dispersion forces act"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which property is directly influenced by intermolecular forces?", "Atomic number", "Boiling point", "Nuclear charge", "Proton number", "B", "Explanation: Stronger intermolecular forces lead to higher boiling points"),
                ("CHM101", "Intermolecular forces and structure of matter", "Which statement about hydrogen bonding is FALSE?", "It is stronger than dispersion forces", "It occurs in H2O", "It exists in CH4", "It involves highly electronegative atoms", "C", "Explanation: CH4 does not form hydrogen bonds"),

                #Stoichiometry and chemical calculations
                ("CHM101", "Stoichiometry and chemical calculations", "A compound contains 40.0% C, 6.7% H, and 53.3% O by mass. If its molar mass is 180 g/mol, what is its molecular formula?","CH2O","C2H4O2","C6H12O6","C3H6O3","C","Explanation: Empirical formula = CH2O (30 g/mol); 180/30 = 6 → C6H12O6"),
                ("CHM101", "Stoichiometry and chemical calculations", "Which statement about limiting reagent is always correct?","It has the smallest mass","It produces the least product","It is completely consumed in the reaction","It is always a gas","C","Explanation: The limiting reagent is fully consumed first, stopping the reaction"),
                ("CHM101", "Stoichiometry and chemical calculations", "How many moles of O2 are required to completely react with 2 moles of C2H6 in the combustion reaction?","3","5","7","4","C","Explanation: 2C2H6 + 7O2 → 4CO2 + 6H2O"),
                ("CHM101", "Stoichiometry and chemical calculations", "What is the percentage composition of oxygen in H2SO4?","65.3%","32.7%","49.0%","40.0%","A","Explanation: O = 64, total = 98 → (64/98)×100 ≈ 65.3%"),
                ("CHM101", "Stoichiometry and chemical calculations", "If 10 g of CaCO3 decomposes completely, what mass of CO2 is produced? (CaCO3 → CaO + CO2)","4.4 g","2.2 g","6.6 g","8.8 g","A","Explanation: 100 g CaCO3 → 44 g CO2; 10 g → 4.4 g"),
                ("CHM101", "Stoichiometry and chemical calculations", "Which condition must be met for coefficients in a balanced equation?","Atoms must be conserved","Mass must decrease","Energy must be zero","Volume must be constant","A","Explanation: Law of conservation of mass requires equal atoms on both sides"),
                ("CHM101", "Stoichiometry and chemical calculations", "How many molecules are in 0.5 moles of a substance?","3.01×10^23","6.02×10^23","1.20×10^24","2.50×10^23","A","Explanation: 0.5 × Avogadro’s number = 3.01×10^23"),
                ("CHM101", "Stoichiometry and chemical calculations", "What is the empirical formula of C6H12O6?","CH2O","C2H4O2","C3H6O3","CHO","A","Explanation: Simplest ratio dividing all by 6 → CH2O"),
                ("CHM101", "Stoichiometry and chemical calculations", "Which reactant is in excess if 4 moles H2 react with 1 mole O2?","H2","O2","Both equal","None","A","Explanation: 2H2 + O2 → 2H2O; need 2 moles H2 per O2, so H2 is excess"),
                ("CHM101", "Stoichiometry and chemical calculations", "What mass of NaCl is formed from 2 moles of Na? (2Na + Cl2 → 2NaCl)","58.5 g","117 g","29.25 g","23 g","B","Explanation: 2 mol Na → 2 mol NaCl; molar mass NaCl = 58.5 → 117 g"),
                ("CHM101", "Stoichiometry and chemical calculations", "Which quantity is directly used to determine empirical formula?","Mole ratio","Mass ratio","Volume ratio","Density","A","Explanation: Empirical formulas depend on mole ratios"),
                ("CHM101", "Stoichiometry and chemical calculations", "If 1 mole of gas occupies 22.4 L at STP, what volume does 0.25 mol occupy?","5.6 L","11.2 L","22.4 L","44.8 L","A","Explanation: 0.25 × 22.4 = 5.6 L"),
                ("CHM101", "Stoichiometry and chemical calculations", "Which step comes first in stoichiometric calculations?","Convert grams to moles","Balance equation","Calculate mass","Find limiting reagent","B","Explanation: Balanced equation is required before mole relationships"),
                ("CHM101", "Stoichiometry and chemical calculations", "What is the limiting reagent if 3 mol N2 reacts with 6 mol H2? (N2 + 3H2 → 2NH3)","N2","H2","NH3","None","B","Explanation: Need 9 mol H2 for 3 mol N2; only 6 available → H2 limiting"),
                ("CHM101", "Stoichiometry and chemical calculations", "How many moles of CO2 are produced from 1 mole of C3H8 combustion?","1","2","3","4","C","Explanation: C3H8 + 5O2 → 3CO2 + 4H2O"),
                ("CHM101", "Stoichiometry and chemical calculations", "What is the molar mass of Al2(SO4)3?","342 g/mol","300 g/mol","250 g/mol","200 g/mol","A","Explanation: 2(27)+3(32+64)=342 g/mol"),
                ("CHM101", "Stoichiometry and chemical calculations", "Which factor does NOT affect percentage yield?","Experimental error","Side reactions","Purity of reactants","Color of product","D","Explanation: Color does not influence yield calculations"),
                ("CHM101", "Stoichiometry and chemical calculations", "What is the empirical formula if mole ratio is C:H:O = 1:2:1?","CH2O","C2H4O2","CHO","CH4O","A","Explanation: Already simplest ratio"),
                ("CHM101", "Stoichiometry and chemical calculations", "If theoretical yield is 50 g and actual yield is 40 g, percentage yield is?","80%","75%","60%","90%","A","Explanation: (40/50)×100 = 80%"),
                ("CHM101", "Stoichiometry and chemical calculations", "Which statement about mole concept is most accurate?","1 mole equals 1 gram","1 mole contains Avogadro’s number of particles","1 mole equals 22.4 g always","1 mole depends on temperature","B","Explanation: Mole is defined by Avogadro’s number of entities"),

                #Chemical reactions
                ("CHM101", "Chemical reactions", "Which reaction type is represented by: 2KClO3 → 2KCl + 3O2?","Combination","Decomposition","Single displacement","Double displacement","B","Explanation: One compound breaks down into simpler substances → decomposition"),
