                ("CHM101", "Chemical reactions", "Oxidation number of sulfur in H2SO4 is?","+2","+4","+6","-2","C","Explanation: S = +6 in H2SO4"),
                ("CHM101", "Chemical reactions", "Which is the correct balanced equation for combustion of C2H4?","C2H4 + 2O2 → 2CO2 + 2H2O","C2H4 + 3O2 → 2CO2 + 2H2O","2C2H4 + 3O2 → 4CO2 + 4H2O","C2H4 + O2 → CO2 + H2O","B","Explanation: Balanced: C2H4 + 3O2 → 2CO2 + 2H2O"),
                ("CHM101", "Chemical reactions", "Which process involves oxidation?","Gain of hydrogen","Loss of oxygen","Loss of electrons","Decrease in oxidation state","C","Explanation: Oxidation is loss of electrons"),
                ("CHM101", "Chemical reactions", "Identify the reducing agent: Fe2O3 + 3CO → 2Fe + 3CO2","Fe2O3","CO","Fe","CO2","B","Explanation: CO reduces Fe2O3 and is oxidized"),
                ("CHM101", "Chemical reactions", "Which reaction shows single displacement?","NaCl + AgNO3 → AgCl + NaNO3","Zn + 2HCl → ZnCl2 + H2","CaCO3 → CaO + CO2","2H2 + O2 → 2H2O","B","Explanation: Zn replaces H from acid"),
                ("CHM101", "Chemical reactions", "Balance: Al + O2 → Al2O3. Coefficient of Al?","2","3","4","6","C","Explanation: 4Al + 3O2 → 2Al2O3"),
                ("CHM101", "Chemical reactions", "Which has oxidation number zero?","Na+","Cl2","O2-","H+","B","Explanation: Free elements have oxidation number 0"),
                ("CHM101", "Chemical reactions", "Which reaction type is combustion always classified as?","Endothermic only","Redox reaction","Double displacement","Neutralization","B","Explanation: Combustion involves oxidation and reduction"),
                ("CHM101", "Chemical reactions", "In redox reactions, electrons are transferred from?","Oxidizing to reducing agent","Reducing to oxidizing agent","Both simultaneously","Neither","B","Explanation: Reducing agent donates electrons"),
                ("CHM101", "Chemical reactions", "Which compound undergoes both oxidation and reduction?","NaCl","H2O","H2O2","CO2","C","Explanation: H2O2 can act as oxidizing and reducing agent"),
                ("CHM101", "Chemical reactions", "Balance: KMnO4 + HCl → KCl + MnCl2 + Cl2 + H2O. Coefficient of HCl?","8","10","12","16","D","Explanation: Balanced equation requires 16 HCl"),
                ("CHM101", "Chemical reactions", "Which change represents reduction?","Fe2+ → Fe3+","Cl- → Cl2","Cu2+ → Cu","H2 → 2H+","C","Explanation: Cu2+ gains electrons to form Cu"),

                #State of matter and gas laws
                ("CHM101", "State of matter and gas laws", "According to the kinetic theory, which statement is correct for ideal gases?","Particles have strong intermolecular forces","Particles occupy significant volume","Collisions are perfectly elastic","Energy decreases during collision","C","Explanation: Ideal gas particles collide elastically with no energy loss"),
                ("CHM101", "State of matter and gas laws", "Boyle’s law states that pressure is inversely proportional to volume at constant?","Temperature","Mass","Density","Moles","A","Explanation: Boyle’s law applies at constant temperature"),
                ("CHM101", "State of matter and gas laws", "If pressure of a gas doubles at constant temperature, volume becomes?","Half","Double","Triple","Constant","A","Explanation: P ∝ 1/V so doubling P halves V"),
                ("CHM101", "State of matter and gas laws", "Charles’ law relates volume directly to?","Pressure","Temperature (Kelvin)","Mass","Density","B","Explanation: V ∝ T in Kelvin"),
                ("CHM101", "State of matter and gas laws", "A gas occupies 2 L at 300 K. What is its volume at 600 K (constant pressure)?","2 L","3 L","4 L","6 L","C","Explanation: V2 = V1 × T2/T1 = 2 × (600/300) = 4 L"),
                ("CHM101", "State of matter and gas laws", "Which unit must temperature be in for gas law calculations?","Celsius","Fahrenheit","Kelvin","Rankine","C","Explanation: Kelvin is absolute temperature scale"),
                ("CHM101", "State of matter and gas laws", "Which assumption is NOT part of kinetic theory?","Gas particles move randomly","Collisions are inelastic","No intermolecular forces","Volume of particles negligible","B","Explanation: Collisions are elastic, not inelastic"),
                ("CHM101", "State of matter and gas laws", "What happens to pressure if volume decreases and temperature remains constant?","Decreases","Increases","Remains constant","Becomes zero","B","Explanation: Boyle’s law → inverse relationship"),
                ("CHM101", "State of matter and gas laws", "Ideal gas equation is given by?","PV = nRT","P = nRT/V","V = nRT/P","All of the above","D","Explanation: All are rearrangements of PV = nRT"),
                ("CHM101", "State of matter and gas laws", "Which gas deviates most from ideal behavior?","Low pressure, high temperature","High pressure, low temperature","Low pressure, low temperature","High temperature only","B","Explanation: Real gases deviate at high P and low T"),
                ("CHM101", "State of matter and gas laws", "If temperature increases at constant volume, pressure?","Decreases","Remains constant","Increases","Becomes zero","C","Explanation: P ∝ T at constant V (Gay-Lussac’s law)"),
                ("CHM101", "State of matter and gas laws", "What is the value of R in SI units?","0.0821 L·atm/mol·K","8.314 J/mol·K","1.987 cal/mol·K","62.4 L·mmHg/mol·K","B","Explanation: SI unit of R = 8.314 J/mol·K"),
                ("CHM101", "State of matter and gas laws", "Which factor does NOT affect gas pressure in a container?","Number of particles","Temperature","Volume","Color of gas","D","Explanation: Color has no effect on pressure"),
                ("CHM101", "State of matter and gas laws", "A gas has pressure 1 atm and volume 5 L. If volume becomes 10 L, new pressure is?","0.5 atm","2 atm","5 atm","10 atm","A","Explanation: P1V1 = P2V2 → P2 = (1×5)/10 = 0.5 atm"),
                ("CHM101", "State of matter and gas laws", "What is the main cause of gas pressure?","Mass of particles","Collisions with container walls","Color of gas","Shape of container","B","Explanation: Pressure arises from particle collisions"),
                ("CHM101", "State of matter and gas laws", "Which gas law explains hot air balloons rising?","Boyle’s law","Charles’ law","Avogadro’s law","Dalton’s law","B","Explanation: Increase in temperature increases volume"),
                ("CHM101", "State of matter and gas laws", "At STP, 1 mole of ideal gas occupies?","11.2 L","22.4 L","44.8 L","1 L","B","Explanation: Standard molar volume is 22.4 L"),
                ("CHM101", "State of matter and gas laws", "If n increases while T and V remain constant, pressure?","Decreases","Increases","Remains constant","Becomes zero","B","Explanation: From PV = nRT, P ∝ n"),
                ("CHM101", "State of matter and gas laws", "Which condition favors ideal gas behavior?","Strong forces","Large particle volume","High temperature, low pressure","Low temperature, high pressure","C","Explanation: Minimizes intermolecular interactions"),
                ("CHM101", "State of matter and gas laws", "What happens to kinetic energy when temperature doubles (Kelvin)?","Halves","Remains constant","Doubles","Quadruples","C","Explanation: Average kinetic energy ∝ temperature"),

