                ("CHM101", "Thermochemistry and thermodynamics", "Which statement correctly defines enthalpy change (ΔH)?","Heat absorbed at constant volume","Heat absorbed at constant pressure","Total internal energy change","Work done by the system","B","Explanation: ΔH is heat change at constant pressure"),
                ("CHM101", "Thermochemistry and thermodynamics", "A reaction with ΔH < 0 is described as?","Endothermic","Isothermal","Exothermic","Adiabatic","C","Explanation: Negative ΔH means heat is released"),
                ("CHM101", "Thermochemistry and thermodynamics", "Which condition makes a reaction spontaneous at all temperatures?","ΔH > 0, ΔS < 0","ΔH < 0, ΔS > 0","ΔH > 0, ΔS > 0","ΔH < 0, ΔS < 0","B","Explanation: Both favorable enthalpy and entropy"),
                ("CHM101", "Thermochemistry and thermodynamics", "What is the unit of entropy (ΔS)?","J","J/mol","J/mol·K","KJ/mol","C","Explanation: Entropy is energy per mole per Kelvin"),
                ("CHM101", "Thermochemistry and thermodynamics", "If ΔG is negative, the reaction is?","Non-spontaneous","At equilibrium","Spontaneous","Endothermic","C","Explanation: Negative ΔG indicates spontaneity"),
                ("CHM101", "Thermochemistry and thermodynamics", "Using ΔG = ΔH − TΔS, what happens if ΔH = 0 and ΔS > 0?","Always non-spontaneous","Spontaneous at all T","Spontaneous only at low T","Equilibrium","B","Explanation: ΔG = −TΔS < 0 always"),
                ("CHM101", "Thermochemistry and thermodynamics", "Which law states that total enthalpy change is independent of pathway?","First law","Second law","Hess’s law","Boyle’s law","C","Explanation: Hess’s law depends only on initial and final states"),
                ("CHM101", "Thermochemistry and thermodynamics", "If a reaction is reversed, ΔH becomes?","Zero","Same sign","Opposite sign","Double","C","Explanation: Enthalpy changes sign when reversed"),
                ("CHM101", "Thermochemistry and thermodynamics", "Which process increases entropy?","Freezing water","Condensation","Melting ice","Gas compression","C","Explanation: Disorder increases in melting"),
                ("CHM101", "Thermochemistry and thermodynamics", "If ΔH > 0 and ΔS > 0, reaction is spontaneous at?","Low temperature","High temperature","All temperatures","No temperature","B","Explanation: TΔS dominates at high T"),
                ("CHM101", "Thermochemistry and thermodynamics", "Which represents the first law of thermodynamics?","Energy cannot be created or destroyed","Entropy always increases","Heat flows from cold to hot","Work equals pressure × volume","A","Explanation: Conservation of energy"),
                ("CHM101", "Thermochemistry and thermodynamics", "What is ΔG at equilibrium?","Positive","Negative","Zero","Infinite","C","Explanation: At equilibrium, ΔG = 0"),
                ("CHM101", "Thermochemistry and thermodynamics", "Which factor does NOT affect ΔG?","Temperature","Entropy","Enthalpy","Pressure (in standard form)","D","Explanation: ΔG = ΔH − TΔS"),
                ("CHM101", "Thermochemistry and thermodynamics", "If ΔG > 0, reaction is?","Spontaneous","Non-spontaneous","At equilibrium","Reversible","B","Explanation: Positive ΔG means non-spontaneous"),
                ("CHM101", "Thermochemistry and thermodynamics", "Which reaction has highest entropy change?","Solid → liquid","Liquid → gas","Gas → liquid","Solid → solid","B","Explanation: Gas phase has highest disorder"),
                ("CHM101", "Thermochemistry and thermodynamics", "In Hess’s law, if equations are multiplied, ΔH is?","Unchanged","Divided","Multiplied accordingly","Zero","C","Explanation: ΔH scales with coefficients"),
                ("CHM101", "Thermochemistry and thermodynamics", "Which process is endothermic?","Combustion","Freezing","Evaporation","Condensation","C","Explanation: Evaporation absorbs heat"),
                ("CHM101", "Thermochemistry and thermodynamics", "If ΔH < 0 and ΔS < 0, reaction is spontaneous at?","High temperature","Low temperature","All temperatures","Never","B","Explanation: Favorable at low T"),
                ("CHM101", "Thermochemistry and thermodynamics", "Which statement about entropy is correct?","Measures energy content","Measures disorder","Measures heat only","Measures pressure","B","Explanation: Entropy quantifies randomness"),
                ("CHM101", "Thermochemistry and thermodynamics", "What happens to ΔG when temperature increases for ΔH > 0 and ΔS < 0?","Becomes negative","Becomes more positive","Remains constant","Becomes zero","B","Explanation: TΔS term increases negativity, making ΔG more positive"),

                #Chemical kinetics (rates of reaction)
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which factor does NOT directly affect reaction rate?","Temperature","Concentration","Catalyst","Color of reactants","D","Explanation: Color has no influence on reaction kinetics"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "What is activation energy?","Energy released in reaction","Minimum energy for effective collision","Total energy of reactants","Heat absorbed","B","Explanation: Activation energy is the minimum energy required for reaction"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Increasing temperature generally increases reaction rate because?","Particles become larger","More effective collisions occur","Activation energy decreases to zero","Volume decreases","B","Explanation: Higher temperature increases kinetic energy and collision frequency"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which factor increases reaction rate by lowering activation energy?","Pressure","Temperature","Catalyst","Volume","C","Explanation: Catalysts provide alternative pathway with lower Ea"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "For reaction A → products, rate = k[A]^2. What is order?","Zero order","First order","Second order","Third order","C","Explanation: Power of concentration is 2 → second order"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "If concentration doubles in a first-order reaction, rate becomes?","Half","Same","Double","Quadruple","C","Explanation: Rate ∝ [A]"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which statement is true for zero-order reactions?","Rate depends on concentration","Rate is constant","Rate increases with time","Rate doubles with concentration","B","Explanation: Rate is independent of concentration"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "What happens to activation energy when a catalyst is added?","Increases","Decreases","Remains same","Becomes zero","B","Explanation: Catalyst lowers activation energy"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which has highest reaction rate?","Low temperature, low concentration","High temperature, high concentration","Low temperature, high concentration","High temperature, low concentration","B","Explanation: Both factors increase collisions"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Rate law for reaction: 2A + B → products is experimentally found as rate = k[A][B]. What is order?","1","2","3","Depends on coefficients","B","Explanation: Order = 1 + 1 = 2"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which step determines overall reaction rate?","Fastest step","Slowest step","Final step","Initial step","B","Explanation: Rate-determining step is slowest"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "What is the unit of rate constant for first-order reaction?","s⁻¹","mol/L·s","L/mol·s","mol²/L²·s","A","Explanation: First-order k has unit s⁻¹"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which condition favors faster reaction?","Low surface area","High activation energy","High surface area","Low temperature","C","Explanation: More surface area increases collisions"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "If rate = k[A]^0, what happens when [A] increases?","Rate increases","Rate decreases","Rate unchanged","Rate doubles","C","Explanation: Zero-order rate independent of [A]"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which collision leads to reaction?","Low energy, wrong orientation","High energy, correct orientation","Low energy, correct orientation","High energy, wrong orientation","B","Explanation: Effective collisions need sufficient energy and orientation"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Arrhenius equation relates rate constant to?","Pressure","Volume","Temperature","Concentration","C","Explanation: k = Ae^(-Ea/RT)"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which factor increases rate by increasing collision frequency?","Catalyst","Temperature","Concentration","Activation energy","C","Explanation: Higher concentration increases collisions"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "If reaction is second order, doubling concentration increases rate by?","2 times","3 times","4 times","8 times","C","Explanation: Rate ∝ [A]^2 → 2² = 4"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which graph is linear for first-order reaction?","[A] vs time","ln[A] vs time","1/[A] vs time","Rate vs time","B","Explanation: First-order gives straight line for ln[A] vs time"),
                ("CHM101", "Chemical kinetics (rates of reaction)", "Which statement about catalysts is correct?","They are consumed","They change equilibrium position","They lower activation energy","They increase ΔH","C","Explanation: Catalysts lower Ea without affecting equilibrium"),

                #Chemical equilibrium
                ("CHM101", "Chemical equilibrium", "At dynamic equilibrium, which statement is correct?","Forward reaction stops","Reverse reaction stops","Rates of forward and reverse reactions are equal","Concentrations become zero","C","Explanation: Dynamic equilibrium means equal rates, not stopping reactions"),
                ("CHM101", "Chemical equilibrium", "Which change will shift equilibrium to the right for an exothermic reaction?","Increase temperature","Decrease temperature","Increase pressure always","Add catalyst","B","Explanation: Lowering temperature favors exothermic direction"),
                ("CHM101", "Chemical equilibrium", "What is the unit of Kc?","Always mol/L","Depends on reaction","Always dimensionless","Always atm","B","Explanation: Units depend on stoichiometry"),
                ("CHM101", "Chemical equilibrium", "For reaction: N2 + 3H2 ⇌ 2NH3, increasing pressure shifts equilibrium?","Left","Right","No change","First right then left","B","Explanation: Fewer moles on right side"),
                ("CHM101", "Chemical equilibrium", "Which does NOT affect equilibrium position?","Temperature","Pressure","Catalyst","Concentration","C","Explanation: Catalyst speeds up reaching equilibrium but does not shift it"),
                ("CHM101", "Chemical equilibrium", "If Kc >> 1, reaction favors?","Reactants","Products","Neither","Equilibrium shifts randomly","B","Explanation: Large K means products dominate"),
                ("CHM101", "Chemical equilibrium", "What happens when concentration of reactant increases?","Shifts left","Shifts right","No change","Stops reaction","B","Explanation: System shifts to consume added reactant"),
                ("CHM101", "Chemical equilibrium", "For endothermic reactions, heat acts as?","Product","Catalyst","Reactant","Inhibitor","C","Explanation: Heat is absorbed → acts as reactant"),
                ("CHM101", "Chemical equilibrium", "Relationship between Kp and Kc is?","Kp = Kc","Kp = Kc(RT)^Δn","Kp = Kc/RT","Kp = RT/Kc","B","Explanation: Depends on change in moles of gas"),
                ("CHM101", "Chemical equilibrium", "Which condition increases Kc?","Adding catalyst","Changing pressure","Changing temperature","Changing concentration","C","Explanation: Only temperature affects K"),
                ("CHM101", "Chemical equilibrium", "If Q < K, reaction proceeds?","Backward","Forward","Stops","Randomly","B","Explanation: System moves forward to reach equilibrium"),
                ("CHM101", "Chemical equilibrium", "If Q > K, reaction proceeds?","Forward","Backward","Stops","Explodes","B","Explanation: System shifts backward"),
                ("CHM101", "Chemical equilibrium", "Which expression is correct for Kc of: aA + bB ⇌ cC?","[A]^a[B]^b/[C]^c","[C]^c/[A]^a[B]^b","[C]/[A+B]","[A+B]/[C]","B","Explanation: Products over reactants"),
                ("CHM101", "Chemical equilibrium", "Increasing pressure has no effect when?","Gaseous system","Equal moles of gas both sides","Solid present","Liquid present","B","Explanation: No change in total moles"),
                ("CHM101", "Chemical equilibrium", "Which best describes Le Chatelier’s principle?","System remains constant","System opposes changes","System speeds up reactions","System stops reactions","B","Explanation: Equilibrium shifts to counteract disturbance"),
                ("CHM101", "Chemical equilibrium", "For reaction with Δn = 0, Kp equals?","Zero","Kc","RT","Infinity","B","Explanation: (RT)^0 = 1"),
                ("CHM101", "Chemical equilibrium", "What happens to equilibrium when inert gas is added at constant volume?","Shifts left","Shifts right","No effect","Stops reaction","C","Explanation: Partial pressures unchanged"),
                ("CHM101", "Chemical equilibrium", "If temperature increases in exothermic reaction, K decreases because?","Products increase","Reactants favored","Pressure changes","Volume changes","B","Explanation: Heat added shifts equilibrium to reactants"),
                ("CHM101", "Chemical equilibrium", "Which species are omitted in equilibrium expression?","Gases","Aqueous solutions","Solids and liquids","Ions","C","Explanation: Pure solids/liquids not included"),
                ("CHM101", "Chemical equilibrium", "What is Kc if reaction is reversed?","Same","Reciprocal","Squared","Zero","B","Explanation: K becomes 1/K when reaction is reversed"),

                #Acid, Base and Salts
                ("CHM101", "Acid, Base and Salts", "According to Arrhenius theory, an acid is a substance that?","Accepts protons","Donates electrons","Produces H+ in solution","Produces OH- in solution","C","Explanation: Arrhenius acids increase H+ concentration in aqueous solution"),
                ("CHM101", "Acid, Base and Salts", "According to Brønsted-Lowry, a base is a substance that?","Donates H+","Accepts H+","Produces H+","Produces OH-","B","Explanation: Bases accept protons"),
                ("CHM101", "Acid, Base and Salts", "Which species is amphoteric?","HCl","NaOH","H2O","NH3","C","Explanation: Water can act as both acid and base"),
                ("CHM101", "Acid, Base and Salts", "What is the pH of a solution with [H+] = 1×10⁻³ M?","3","7","11","1","A","Explanation: pH = -log[H+] = 3"),
                ("CHM101", "Acid, Base and Salts", "If pH = 2, the solution is?","Neutral","Weak base","Strong acid","Weak acid","C","Explanation: Low pH indicates strong acidity"),
                ("CHM101", "Acid, Base and Salts", "What is the pOH of a solution with pH = 5?","5","7","9","14","C","Explanation: pH + pOH = 14 → pOH = 9"),
                ("CHM101", "Acid, Base and Salts", "Which pair is conjugate acid-base pair?","HCl/NaCl","NH3/NH4+","NaOH/Na+","H2O/O2","B","Explanation: NH3 accepts H+ to form NH4+"),
                ("CHM101", "Acid, Base and Salts", "Neutralization reaction produces?","Acid only","Base only","Salt and water","Gas only","C","Explanation: Acid + Base → Salt + Water"),
                ("CHM101", "Acid, Base and Salts", "Which salt undergoes hydrolysis?","NaCl","KNO3","NH4Cl","Na2SO4","C","Explanation: NH4+ hydrolyzes producing acidic solution"),
                ("CHM101", "Acid, Base and Salts", "Which solution has highest pH?","1×10⁻¹ M HCl","1×10⁻⁷ M HCl","1×10⁻¹ M NaOH","1×10⁻³ M HCl","C","Explanation: Strong base has highest pH"),
                ("CHM101", "Acid, Base and Salts", "What is pH of neutral solution at 25°C?","0","14","7","1","C","Explanation: Neutral pH = 7"),
                ("CHM101", "Acid, Base and Salts", "Which is a strong base?","NH3","NaOH","CH3COOH","H2CO3","B","Explanation: NaOH fully dissociates"),
                ("CHM101", "Acid, Base and Salts", "Which acid is weak?","HCl","HNO3","CH3COOH","H2SO4","C","Explanation: Acetic acid partially ionizes"),
                ("CHM101", "Acid, Base and Salts", "If [OH-] = 1×10⁻² M, pOH =?","2","12","10","1","A","Explanation: pOH = -log[OH-] = 2"),
                ("CHM101", "Acid, Base and Salts", "What happens to pH when acid is diluted?","Decreases","Increases","Remains same","Becomes zero","B","Explanation: Dilution lowers H+ concentration"),
                ("CHM101", "Acid, Base and Salts", "Which salt forms basic solution in water?","NH4Cl","NaCl","Na2CO3","HCl","C","Explanation: CO3²⁻ hydrolyzes to produce OH-"),
                ("CHM101", "Acid, Base and Salts", "Which defines hydrolysis?","Reaction with oxygen","Reaction with water","Reaction with acid","Reaction with base","B","Explanation: Hydrolysis involves reaction with water"),
                ("CHM101", "Acid, Base and Salts", "What is pH of 1×10⁻¹⁴ M H+ solution?","14","7","0","1","B","Explanation: Due to water autoionization, pH ≈ 7"),
                ("CHM101", "Acid, Base and Salts", "Which statement is true about strong acids?","Partially ionize","Fully ionize","Do not ionize","React slowly","B","Explanation: Strong acids dissociate completely"),
                ("CHM101", "Acid, Base and Salts", "Which ion acts as a base in water?","Cl-","NO3-","NH4+","CO3²⁻","D","Explanation: CO3²⁻ accepts H+ forming HCO3⁻"),

                #Eletrochemistry
                ("CHM101", "Eletrochemistry", "In a galvanic cell, electrons flow from?","Cathode to anode","Anode to cathode","Salt bridge to electrode","Electrolyte to electrode","B","Explanation: Oxidation at anode releases electrons which flow to cathode"),
                ("CHM101", "Eletrochemistry", "Which process occurs at the anode?","Reduction","Oxidation","Neutralization","Hydrolysis","B","Explanation: Anode is the site of oxidation"),
                ("CHM101", "Eletrochemistry", "In electrolysis, the cathode is?","Positive","Negative","Neutral","Variable","B","Explanation: Cathode is negative in electrolytic cells"),
                ("CHM101", "Eletrochemistry", "Which species is reduced in: Cu2+ + 2e- → Cu?","Cu","Cu2+","e-","None","B","Explanation: Cu2+ gains electrons → reduction"),
                ("CHM101", "Eletrochemistry", "Standard electrode potential is measured under?","Any conditions","Non-standard conditions","Standard conditions","High pressure only","C","Explanation: 1M, 1 atm, 25°C"),
                ("CHM101", "Eletrochemistry", "Which has highest tendency to be reduced?","Lowest E° value","Highest E° value","Zero E° value","Negative E° always","B","Explanation: Higher reduction potential means stronger oxidizing agent"),
                ("CHM101", "Eletrochemistry", "In Daniell cell, Zn acts as?","Cathode","Anode","Electrolyte","Salt bridge","B","Explanation: Zn is oxidized at anode"),
                ("CHM101", "Eletrochemistry", "Which law relates mass deposited to charge passed?","Boyle’s law","Hess’s law","Faraday’s law","Charles’ law","C","Explanation: Faraday’s laws govern electrolysis"),
                ("CHM101", "Eletrochemistry", "One Faraday equals?","96500 C","1 C","1000 C","6.02×10²³ C","A","Explanation: Charge of 1 mole of electrons"),
                ("CHM101", "Eletrochemistry", "Which reaction occurs at cathode during electrolysis of molten NaCl?","Na → Na+","Cl- → Cl2","Na+ → Na","Cl2 → Cl-","C","Explanation: Reduction of Na+ to Na metal"),
                ("CHM101", "Eletrochemistry", "Cell potential is calculated as?","E°anode - E°cathode","E°cathode - E°anode","Sum of potentials","Product of potentials","B","Explanation: Ecell = Ecathode - Eanode"),
                ("CHM101", "Eletrochemistry", "Which component maintains electrical neutrality?","Electrode","Salt bridge","Wire","Electrolyte only","B","Explanation: Salt bridge balances charge"),
                ("CHM101", "Eletrochemistry", "If E°cell is positive, reaction is?","Non-spontaneous","Spontaneous","At equilibrium","Reversible only","B","Explanation: Positive E° indicates spontaneous reaction"),
                ("CHM101", "Eletrochemistry", "Which metal is most easily oxidized?","Highest reduction potential","Lowest reduction potential","Zero potential","Same potential","B","Explanation: Lower E° means more easily oxidized"),
                ("CHM101", "Eletrochemistry", "What is deposited when CuSO4 is electrolyzed using inert electrodes?","SO4²-","Cu","O2","H2","B","Explanation: Cu2+ is reduced to Cu"),
                ("CHM101", "Eletrochemistry", "Faraday’s second law states?","Mass ∝ time","Mass ∝ current","Mass ∝ equivalent weight","Mass ∝ voltage","C","Explanation: Different substances deposit proportional to equivalent weights"),
                ("CHM101", "Eletrochemistry", "Which is oxidizing agent?","Loses electrons","Gains electrons","Neutral substance","Does not react","B","Explanation: Oxidizing agent gains electrons"),
                ("CHM101", "Eletrochemistry", "In electrochemical cell, oxidation number of element that is reduced?","Increases","Decreases","Remains same","Becomes zero always","B","Explanation: Reduction lowers oxidation number"),
                ("CHM101", "Eletrochemistry", "What happens when current increases in electrolysis?","Mass decreases","Mass increases","No effect","Stops reaction","B","Explanation: More charge → more deposition"),
                ("CHM101", "Eletrochemistry", "Which condition increases cell potential?","Higher temperature only","Higher concentration difference","Lower pressure","Adding catalyst","B","Explanation: Greater concentration gradient increases potential"),

                #Radioactivity (intriductory)
                ("CHM101", "Radioactivity (intriductory)", "Which radiation has the highest ionizing power?","Alpha","Beta","Gamma","X-ray","A","Explanation: Alpha particles are highly ionizing due to large mass and +2 charge"),
                ("CHM101", "Radioactivity (intriductory)", "Which radiation has the greatest penetrating power?","Alpha","Beta","Gamma","Neutron","C","Explanation: Gamma rays penetrate deepest due to no charge and high energy"),
                ("CHM101", "Radioactivity (intriductory)", "Emission of a beta particle results in?","Decrease in mass number","Increase in atomic number","Decrease in atomic number","No change","B","Explanation: Neutron converts to proton, increasing atomic number"),
                ("CHM101", "Radioactivity (intriductory)", "Which particle is emitted in alpha decay?","Electron","Proton","Helium nucleus","Neutron","C","Explanation: Alpha particle is 2p + 2n (He nucleus)"),
                ("CHM101", "Radioactivity (intriductory)", "Half-life is defined as time taken for?","All nuclei to decay","Half of nuclei to decay","Quarter nuclei to decay","One nucleus to decay","B","Explanation: Half-life is time for 50% decay"),
                ("CHM101", "Radioactivity (intriductory)", "If half-life is 10 days, fraction remaining after 30 days?","1/2","1/4","1/8","1/16","C","Explanation: 3 half-lives → (1/2)^3 = 1/8"),
                ("CHM101", "Radioactivity (intriductory)", "Which radiation is deflected by electric field?","Gamma only","Alpha and beta","Gamma and alpha","None","B","Explanation: Charged particles (alpha, beta) are deflected"),
                ("CHM101", "Radioactivity (intriductory)", "Gamma rays are?","Charged particles","Electrons","Electromagnetic waves","Protons","C","Explanation: Gamma is high-energy EM radiation"),
                ("CHM101", "Radioactivity (intriductory)", "In nuclear equation, mass number must be?","Ignored","Conserved","Decreased","Increased","B","Explanation: Total mass number is conserved"),
                ("CHM101", "Radioactivity (intriductory)", "Which change occurs in alpha decay?","A-4, Z-2","A-1, Z+1","A unchanged, Z+1","A-2, Z-1","A","Explanation: Alpha emission reduces mass by 4 and atomic number by 2"),
                ("CHM101", "Radioactivity (intriductory)", "Radioactive decay is?","Temperature dependent","Pressure dependent","Independent of external conditions","Catalyst dependent","C","Explanation: Decay is spontaneous and unaffected by conditions"),
                ("CHM101", "Radioactivity (intriductory)", "If initial amount is 80g and half-life is 5h, amount after 15h?","40g","20g","10g","5g","C","Explanation: 3 half-lives → 80→40→20→10g"),
                ("CHM101", "Radioactivity (intriductory)", "Which radiation has negative charge?","Alpha","Beta","Gamma","Neutron","B","Explanation: Beta particles are electrons (-1 charge)"),
                ("CHM101", "Radioactivity (intriductory)", "Which radiation is least ionizing?","Alpha","Beta","Gamma","Proton","C","Explanation: Gamma has lowest ionizing power"),
                ("CHM101", "Radioactivity (intriductory)", "In beta decay, a neutron becomes?","Proton + electron","Proton only","Electron only","Alpha particle","A","Explanation: n → p + e-"),
                ("CHM101", "Radioactivity (intriductory)", "Nuclear reactions involve changes in?","Electrons only","Nucleus","Orbitals","Molecules","B","Explanation: Nuclear reactions affect nucleus"),
                ("CHM101", "Radioactivity (intriductory)", "Which equation is balanced?","14C → 14N + β","14C → 13N + β","14C → 14N + α","14C → 12C + α","A","Explanation: Mass and atomic numbers conserved"),
                ("CHM101", "Radioactivity (intriductory)", "After 2 half-lives, remaining amount is?","1/2","1/3","1/4","1/8","C","Explanation: (1/2)^2 = 1/4"),
                ("CHM101", "Radioactivity (intriductory)", "Which radiation can pass through paper easily?","Alpha","Beta","Gamma","None","C","Explanation: Gamma penetrates paper easily"),
                ("CHM101", "Radioactivity (intriductory)", "Activity of radioactive substance decreases because?","Atoms disappear","Nuclei decay over time","Mass increases","Energy lost","B","Explanation: Number of undecayed nuclei decreases over time"),

                        #BIO 101 - Introduction to biology
                ("BIO101", "Introduction to biology", "Which of the following best defines Biology?", "Study of plants only", "Study of animals only", "Study of living organisms and their interactions", "Study of non-living things", "C", "Explanation: Biology is the scientific study of life and living organisms, including their structure, function, growth, and interactions."), 
                ("BIO101", "Introduction to biology", "Which branch of Biology deals specifically with microscopic organisms?", "Botany", "Zoology", "Microbiology", "Anatomy", "C", "Explanation: Microbiology studies organisms too small to be seen with the naked eye, such as bacteria and viruses."),
                ("BIO101", "Introduction to biology", "Which of the following is NOT a characteristic of living organisms?", "Respiration", "Movement", "Photosynthesis", "Growth", "C", "Explanation: Photosynthesis is not universal to all living organisms, unlike respiration, movement, and growth."),
                ("BIO101", "Introduction to biology", "An organism that can respond to stimuli but cannot move from place to place still satisfies which characteristic of life?", "Movement", "Sensitivity", "Excretion", "Nutrition", "B", "Explanation: Sensitivity refers to the ability to respond to stimuli, even without locomotion."),
                ("BIO101", "Introduction to biology", "Which level of organization correctly follows the sequence from simplest to most complex?", "Cell → Organ → Tissue → System", "Tissue → Cell → Organ → System", "Cell → Tissue → Organ → System", "Organ → Tissue → Cell → System", "C", "Explanation: The correct biological hierarchy is cell, tissue, organ, and then system."),
                ("BIO101", "Introduction to biology", "Which of the following best distinguishes Zoology from Botany?", "Zoology studies microorganisms", "Botany studies animals", "Zoology studies animals while Botany studies plants", "Both study fungi only", "C", "Explanation: Zoology focuses on animals, while Botany focuses on plants."),
                ("BIO101", "Introduction to biology", "Which of the following processes is directly responsible for releasing energy in living organisms?", "Respiration", "Excretion", "Nutrition", "Movement", "A", "Explanation: Respiration breaks down food substances to release energy."),
                ("BIO101", "Introduction to biology", "Which characteristic of life involves removal of metabolic waste?", "Respiration", "Excretion", "Nutrition", "Growth", "B", "Explanation: Excretion is the process of eliminating waste products from the body."),
                ("BIO101", "Introduction to biology", "Which branch of Biology focuses on the structure of organisms?", "Physiology", "Ecology", "Anatomy", "Genetics", "C", "Explanation: Anatomy deals with the structure of organisms, while physiology deals with function."),
                ("BIO101", "Introduction to biology", "Which of the following best explains growth in living organisms?", "Increase in size only", "Irreversible increase in size and complexity", "Temporary increase in mass", "Movement of body parts", "B", "Explanation: Growth involves permanent increase in size and complexity."),
                ("BIO101", "Introduction to biology", "Which of the following is the correct definition of a tissue?", "Group of organs working together", "Group of similar cells performing a specific function", "Smallest unit of life", "Collection of systems", "B", "Explanation: A tissue is a group of similar cells that work together to perform a function."),
                ("BIO101", "Introduction to biology", "Which branch of Biology studies the relationship between organisms and their environment?", "Genetics", "Ecology", "Anatomy", "Cytology", "B", "Explanation: Ecology focuses on interactions between organisms and their environment."),
                ("BIO101", "Introduction to biology", "Which of the following is the smallest unit capable of carrying out all life processes?", "Atom", "Molecule", "Cell", "Tissue", "C", "Explanation: The cell is the basic unit of life capable of performing all vital functions."),
                ("BIO101", "Introduction to biology", "Which of the following statements about movement in living organisms is TRUE?", "All movement involves locomotion", "Plants do not exhibit movement", "Movement can occur at cellular level", "Only animals can move", "C", "Explanation: Movement includes internal movements such as cytoplasmic streaming, not just locomotion."),
                ("BIO101", "Introduction to biology", "Which characteristic of life ensures continuity of species?", "Growth", "Reproduction", "Respiration", "Sensitivity", "B", "Explanation: Reproduction allows organisms to produce offspring and maintain species continuity."),
                ("BIO101", "Introduction to biology", "Which level of organization consists of different tissues working together?", "Cell", "Organ", "System", "Organism", "B", "Explanation: An organ is made up of different tissues working together for specific functions."),
                ("BIO101", "Introduction to biology", "Which of the following is an example of a system in biological organization?", "Heart", "Blood", "Circulatory system", "Muscle cell", "C", "Explanation: A system is composed of organs working together, such as the circulatory system."),
                ("BIO101", "Introduction to biology", "Which branch of Biology would study inheritance patterns?", "Ecology", "Genetics", "Anatomy", "Physiology", "B", "Explanation: Genetics focuses on heredity and variation in organisms."),
                ("BIO101", "Introduction to biology", "Which of the following is NOT part of MRS GREN?", "Nutrition", "Growth", "Respiration", "Circulation", "D", "Explanation: Circulation is not included in MRS GREN, which stands for Movement, Respiration, Sensitivity, Growth, Reproduction, Excretion, Nutrition."),
                ("BIO101", "Introduction to biology", "Why are viruses often excluded from living organisms?", "They cannot reproduce", "They lack cellular structure and independent metabolism", "They are too small", "They do not contain DNA", "B", "Explanation: Viruses lack cellular organization and cannot carry out metabolic processes independently."),

                #Scientific method in biology
                ("BIO101", "Scientific method in biology", "Which of the following best describes a scientific hypothesis?", "A proven fact", "A testable and falsifiable statement", "An observation without explanation", "A random guess", "B", "Explanation: A hypothesis must be testable and capable of being proven false."), 
                ("BIO101", "Scientific method in biology", "Which step in the scientific method involves gathering initial information using senses or instruments?", "Experiment", "Conclusion", "Observation", "Hypothesis", "C", "Explanation: Observation is the first step where data is collected through senses or tools."),
                ("BIO101", "Scientific method in biology", "Which of the following distinguishes accuracy from precision?", "Accuracy is repeatability, precision is closeness to true value", "Accuracy is closeness to true value, precision is repeatability", "Both are the same", "Precision measures correctness only", "B", "Explanation: Accuracy refers to closeness to the true value, while precision refers to consistency of results."),
                ("BIO101", "Scientific method in biology", "In an experiment, the variable that is deliberately changed is called?", "Dependent variable", "Controlled variable", "Independent variable", "Constant", "C", "Explanation: The independent variable is the one the experimenter manipulates."),
                ("BIO101", "Scientific method in biology", "Which of the following is the dependent variable?", "The variable that is controlled", "The variable that is measured as an outcome", "The variable that is changed", "The constant factor", "B", "Explanation: The dependent variable is what is measured to observe the effect of changes."),
                ("BIO101", "Scientific method in biology", "Which type of variable must be kept constant to ensure a fair test?", "Independent variable", "Dependent variable", "Controlled variable", "Random variable", "C", "Explanation: Controlled variables are kept constant to ensure that results are due only to the independent variable."),
                ("BIO101", "Scientific method in biology", "Which of the following best describes precision?", "Closeness to actual value", "Consistency of repeated measurements", "Lack of error", "Correct conclusion", "B", "Explanation: Precision refers to how consistent repeated measurements are."),
                ("BIO101", "Scientific method in biology", "Which of the following would most likely reduce experimental error?", "Increasing sample size", "Changing variables frequently", "Ignoring controls", "Reducing observations", "A", "Explanation: Larger sample sizes reduce random errors and increase reliability."),
                ("BIO101", "Scientific method in biology", "Which step follows hypothesis in the scientific method?", "Conclusion", "Experiment", "Observation", "Theory formation", "B", "Explanation: After forming a hypothesis, experiments are conducted to test it."),
                ("BIO101", "Scientific method in biology", "Which of the following is NOT a characteristic of a good experiment?", "Reproducibility", "Control of variables", "Bias", "Objectivity", "C", "Explanation: A good experiment must be unbiased, reproducible, and controlled."),
                ("BIO101", "Scientific method in biology", "A student measures the length of a leaf three times and gets 5.1 cm, 5.1 cm, and 5.1 cm, but the actual length is 5.5 cm. This shows?", "High accuracy, low precision", "Low accuracy, high precision", "High accuracy, high precision", "Low accuracy, low precision", "B", "Explanation: The measurements are consistent (precise) but not close to the true value (not accurate)."),
                ("BIO101", "Scientific method in biology", "Which of the following best defines a control in an experiment?", "A variable that is changed", "A standard for comparison", "A measured outcome", "An error margin", "B", "Explanation: A control provides a baseline to compare experimental results."),
                ("BIO101", "Scientific method in biology", "Which of the following is the main purpose of repeating an experiment?", "To waste time", "To confirm reliability of results", "To change variables", "To increase bias", "B", "Explanation: Repetition ensures results are consistent and reliable."),
                ("BIO101", "Scientific method in biology", "Which of the following statements about variables is correct?", "There can only be one variable in an experiment", "Multiple independent variables are always used", "Only one independent variable should be tested at a time", "Dependent variables are controlled", "C", "Explanation: Only one independent variable should be changed to maintain a fair test."),
                ("BIO101", "Scientific method in biology", "Which of the following would be considered a qualitative observation?", "Plant height is 10 cm", "Leaf is green", "Mass is 5 g", "Temperature is 25°C", "B", "Explanation: Qualitative observations describe qualities, not numerical values."),
                ("BIO101", "Scientific method in biology", "Which of the following is a quantitative observation?", "The solution is blue", "The plant is tall", "The temperature is 30°C", "The leaf is rough", "C", "Explanation: Quantitative observations involve numerical measurements."),
                ("BIO101", "Scientific method in biology", "Which step involves interpreting results to determine if the hypothesis is supported?", "Observation", "Conclusion", "Experiment", "Prediction", "B", "Explanation: The conclusion evaluates whether the hypothesis is supported or rejected."),
                ("BIO101", "Scientific method in biology", "Which of the following best explains systematic error?", "Random fluctuations in measurement", "Consistent deviation due to faulty equipment", "Mistakes in calculation only", "Human error only", "B", "Explanation: Systematic errors occur due to consistent faults, such as miscalibrated instruments."),
                ("BIO101", "Scientific method in biology", "Which of the following best defines a fair test?", "Testing multiple variables at once", "Changing all variables randomly", "Keeping all variables constant except one", "Ignoring control setup", "C", "Explanation: A fair test changes only one variable while keeping others constant."),
                ("BIO101", "Scientific method in biology", "Which of the following best differentiates observation from inference?", "Observation is explanation, inference is data collection", "Observation is based on senses, inference is interpretation", "Both are the same", "Inference is always correct", "B", "Explanation: Observations are direct data, while inferences are interpretations based on observations."),

                #Cell Biology
                ("BIO101", "Cell biology", "Which statement is NOT part of the cell theory?", "All living organisms are composed of cells", "Cells arise spontaneously from non-living matter", "The cell is the basic unit of life", "All cells come from pre-existing cells", "B", "Explanation: Cell theory states that cells arise from pre-existing cells, not spontaneously."), 
                ("BIO101", "Cell biology", "Which of the following is a key difference between prokaryotic and eukaryotic cells?", "Prokaryotes have membrane-bound organelles", "Eukaryotes lack a nucleus", "Prokaryotes lack a true nucleus", "Eukaryotes are always unicellular", "C", "Explanation: Prokaryotic cells do not have a membrane-bound nucleus."),
                ("BIO101", "Cell biology", "Which organelle is primarily responsible for ATP production?", "Nucleus", "Ribosome", "Mitochondrion", "Golgi apparatus", "C", "Explanation: Mitochondria are the site of cellular respiration and ATP production."),
                ("BIO101", "Cell biology", "Which of the following structures is present in prokaryotic cells?", "Mitochondria", "Endoplasmic reticulum", "Ribosomes", "Golgi apparatus", "C", "Explanation: Prokaryotes lack membrane-bound organelles but contain ribosomes."),
                ("BIO101", "Cell biology", "Which organelle controls cell activities and contains genetic material?", "Cytoplasm", "Nucleus", "Cell membrane", "Lysosome", "B", "Explanation: The nucleus houses DNA and regulates cellular activities."),
                ("BIO101", "Cell biology", "Which type of transport requires energy (ATP)?", "Diffusion", "Osmosis", "Facilitated diffusion", "Active transport", "D", "Explanation: Active transport moves substances against the concentration gradient using energy."),
                ("BIO101", "Cell biology", "Which of the following best describes diffusion?", "Movement of water across a membrane", "Movement of molecules from low to high concentration", "Movement of molecules from high to low concentration", "Movement requiring ATP", "C", "Explanation: Diffusion is the passive movement of particles down their concentration gradient."),
                ("BIO101", "Cell biology", "Osmosis is best defined as?", "Movement of solute across membrane", "Movement of water across a selectively permeable membrane", "Movement of gases only", "Active transport of ions", "B", "Explanation: Osmosis specifically refers to water movement through a semi-permeable membrane."),
                ("BIO101", "Cell biology", "Which organelle is responsible for protein synthesis?", "Mitochondria", "Ribosome", "Nucleus", "Lysosome", "B", "Explanation: Ribosomes are the sites of protein synthesis."),
                ("BIO101", "Cell biology", "Which organelle modifies, sorts, and packages proteins?", "Golgi apparatus", "Nucleus", "Ribosome", "Mitochondrion", "A", "Explanation: The Golgi apparatus processes and packages proteins for transport."),
                ("BIO101", "Cell biology", "Which of the following is TRUE about cell membranes?", "They are fully permeable", "They are selectively permeable", "They allow only water through", "They are made of cellulose", "B", "Explanation: Cell membranes selectively regulate the movement of substances."),
                ("BIO101", "Cell biology", "Which of the following structures is absent in prokaryotic cells but present in eukaryotic cells?", "Cell membrane", "Ribosome", "Nucleus", "Cytoplasm", "C", "Explanation: Prokaryotes lack a membrane-bound nucleus."),
                ("BIO101", "Cell biology", "Which process does NOT require a membrane protein?", "Facilitated diffusion", "Active transport", "Diffusion", "Osmosis (via aquaporins optional)", "C", "Explanation: Simple diffusion occurs directly through the lipid bilayer without proteins."),
                ("BIO101", "Cell biology", "Which condition will cause a plant cell to become turgid?", "Hypertonic solution", "Isotonic solution", "Hypotonic solution", "Concentrated solution", "C", "Explanation: In a hypotonic solution, water enters the cell, making it turgid."),
                ("BIO101", "Cell biology", "Which organelle contains digestive enzymes for breaking down waste?", "Ribosome", "Lysosome", "Nucleus", "Mitochondrion", "B", "Explanation: Lysosomes contain enzymes that digest cellular waste."),
                ("BIO101", "Cell biology", "Which of the following best explains why prokaryotic cells are smaller than eukaryotic cells?", "They lack DNA", "They lack ribosomes", "They lack membrane-bound organelles", "They cannot reproduce", "C", "Explanation: The absence of complex organelles allows prokaryotes to remain small and simple."),
                ("BIO101", "Cell biology", "Which of the following is TRUE about facilitated diffusion?", "It requires ATP", "It moves substances against gradient", "It uses membrane proteins without energy", "It occurs only in plants", "C", "Explanation: Facilitated diffusion uses proteins to move substances down the gradient without energy."),
                ("BIO101", "Cell biology", "Which structure is responsible for controlling entry and exit of substances in a cell?", "Nucleus", "Cytoplasm", "Cell membrane", "Ribosome", "C", "Explanation: The cell membrane regulates movement of substances into and out of the cell."),
                ("BIO101", "Cell biology", "Which of the following would stop active transport immediately?", "Removal of oxygen supply", "Decrease in temperature", "Removal of ATP", "Increase in concentration gradient", "C", "Explanation: Active transport depends directly on ATP energy."),
                ("BIO101", "Cell biology", "Which statement best compares ribosomes in prokaryotes and eukaryotes?", "Only eukaryotes have ribosomes", "Only prokaryotes have ribosomes", "Both have ribosomes but differ in size", "Neither has ribosomes", "C", "Explanation: Both cell types have ribosomes, but prokaryotic ribosomes are smaller."),

                ("BIO101", "Cell biology", "Which statement correctly extends the modern cell theory beyond the original?", "Cells arise spontaneously under ideal conditions", "Energy flow (metabolism) occurs within cells", "All cells have identical structures", "Cells do not contain hereditary material", "B", "Explanation: Modern cell theory includes that metabolism and energy flow occur within cells."),
                ("BIO101", "Cell biology", "Which of the following observations most directly contradicts spontaneous generation?", "Cells contain DNA", "Cells divide by binary fission", "New cells arise from pre-existing cells", "Cells have membranes", "C", "Explanation: The principle that cells arise from pre-existing cells rejects spontaneous generation."),
                ("BIO101", "Cell biology", "Which organelle’s double membrane and internal folds are essential for maximizing ATP yield?", "Golgi apparatus", "Mitochondrion", "Lysosome", "Peroxisome", "B", "Explanation: The mitochondrion has a double membrane with cristae that increase surface area for ATP production."),
                ("BIO101", "Cell biology", "Which statement about the nucleus is FALSE?", "It contains chromatin", "It is the site of ribosome assembly (nucleolus)", "It is present in all cells", "It is bounded by a double membrane", "C", "Explanation: Prokaryotic cells lack a nucleus."),
                ("BIO101", "Cell biology", "Which structure regulates the movement of molecules between nucleus and cytoplasm?", "Nucleolus", "Nuclear pores", "Chromatin", "Centrioles", "B", "Explanation: Nuclear pores control exchange of materials across the nuclear envelope."),
                ("BIO101", "Cell biology", "Which organelle is primarily responsible for synthesizing proteins destined for secretion?", "Free ribosomes", "Rough endoplasmic reticulum", "Smooth endoplasmic reticulum", "Lysosomes", "B", "Explanation: Ribosomes on the rough ER synthesize proteins for export or membrane insertion."),
                ("BIO101", "Cell biology", "Which of the following pairs is mismatched?", "Mitochondria – ATP production", "Ribosomes – Protein synthesis", "Nucleus – Lipid synthesis", "Golgi apparatus – Protein modification", "C", "Explanation: Lipid synthesis mainly occurs in the smooth ER, not the nucleus."),
                ("BIO101", "Cell biology", "Which feature supports the endosymbiotic theory of mitochondria?", "They lack DNA", "They have a single membrane", "They contain their own circular DNA", "They are formed in the nucleus", "C", "Explanation: Mitochondria possess their own circular DNA similar to prokaryotes."),
                ("BIO101", "Cell biology", "Which organelle modifies and sorts proteins after synthesis?", "Endoplasmic reticulum", "Golgi apparatus", "Nucleus", "Mitochondrion", "B", "Explanation: The Golgi apparatus modifies, sorts, and packages proteins."),
                ("BIO101", "Cell biology", "Which of the following is TRUE about ribosomes?", "They are membrane-bound organelles", "They are found only in eukaryotes", "They can be free or attached to ER", "They synthesize lipids", "C", "Explanation: Ribosomes exist free in cytoplasm or bound to rough ER."),
                ("BIO101", "Cell biology", "Which organelle contains hydrolytic enzymes for intracellular digestion?", "Peroxisome", "Lysosome", "Golgi apparatus", "Nucleus", "B", "Explanation: Lysosomes contain enzymes that break down macromolecules and waste."),
                ("BIO101", "Cell biology", "Which statement best explains why the nucleus is considered the control center?", "It produces ATP", "It stores and regulates genetic information", "It digests waste", "It transports proteins", "B", "Explanation: The nucleus houses DNA and controls gene expression."),
                ("BIO101", "Cell biology", "Which of the following would be most directly affected by damage to ribosomes?", "ATP production", "Protein synthesis", "DNA replication", "Waste breakdown", "B", "Explanation: Ribosomes are the site of protein synthesis."),
                ("BIO101", "Cell biology", "Which organelle is responsible for detoxification and lipid synthesis?", "Rough ER", "Smooth ER", "Golgi apparatus", "Nucleus", "B", "Explanation: Smooth ER synthesizes lipids and detoxifies chemicals."),
                ("BIO101", "Cell biology", "Which of the following best describes chromatin?", "Protein synthesis machinery", "DNA-protein complex in the nucleus", "Membrane channels", "Energy-producing folds", "B", "Explanation: Chromatin consists of DNA wrapped around proteins in the nucleus."),
                ("BIO101", "Cell biology", "Which organelle’s malfunction would most directly lead to accumulation of toxic hydrogen peroxide?", "Lysosome", "Peroxisome", "Golgi apparatus", "Ribosome", "B", "Explanation: Peroxisomes detoxify hydrogen peroxide."),
                ("BIO101", "Cell biology", "Which of the following distinguishes eukaryotic cells from prokaryotic cells?", "Presence of ribosomes", "Presence of cytoplasm", "Membrane-bound organelles", "Ability to reproduce", "C", "Explanation: Eukaryotes possess membrane-bound organelles unlike prokaryotes."),
                ("BIO101", "Cell biology", "Which structure is responsible for assembling ribosomal subunits?", "Chromatin", "Nucleolus", "Nuclear envelope", "Centrosome", "B", "Explanation: The nucleolus synthesizes rRNA and assembles ribosomal subunits."),
                ("BIO101", "Cell biology", "Which organelle would be most abundant in a cell specialized for active transport processes?", "Nucleus", "Mitochondria", "Golgi apparatus", "Ribosomes", "B", "Explanation: Active transport requires ATP, produced by mitochondria."),
                ("BIO101", "Cell biology", "Which statement best summarizes the relationship between structure and function in organelles?", "All organelles have identical structures", "Structure determines function", "Function determines location only", "Organelles are functionless", "B", "Explanation: The specific structure of each organelle enables its specialized function."),

                ("BIO101", "Cell biology", "Which statement best aligns with modern cell theory regarding cell membranes?", "All cells lack membranes", "Cell membranes regulate internal conditions", "Membranes are only in eukaryotes", "Cells are solid structures", "B", "Explanation: Modern cell theory recognizes membranes as essential for regulating the internal environment of cells."),
                ("BIO101", "Cell biology", "Which of the following processes occurs down a concentration gradient without energy?", "Active transport", "Endocytosis", "Diffusion", "Exocytosis", "C", "Explanation: Diffusion is a passive process where particles move from high to low concentration."),
                ("BIO101", "Cell biology", "Which condition is required for osmosis to occur?", "ATP supply", "Carrier proteins only", "Semi-permeable membrane", "High temperature", "C", "Explanation: Osmosis specifically requires a selectively permeable membrane."),
                ("BIO101", "Cell biology", "Which of the following best explains why diffusion rate increases with temperature?", "Particles shrink", "Membrane becomes rigid", "Particles gain kinetic energy", "Concentration gradient disappears", "C", "Explanation: Higher temperature increases kinetic energy, speeding up particle movement."),
                ("BIO101", "Cell biology", "Which of the following is TRUE about active transport?", "It occurs only in plants", "It requires ATP", "It moves substances down gradient", "It does not involve proteins", "B", "Explanation: Active transport requires energy (ATP) to move substances against the gradient."),
                ("BIO101", "Cell biology", "Which factor does NOT affect the rate of diffusion?", "Temperature", "Concentration gradient", "Surface area", "Cell nucleus size", "D", "Explanation: Diffusion rate depends on physical conditions, not nucleus size."),
                ("BIO101", "Cell biology", "Which of the following describes facilitated diffusion?", "Movement against gradient using ATP", "Movement down gradient via membrane proteins", "Movement of water only", "Movement without membrane", "B", "Explanation: Facilitated diffusion uses carrier or channel proteins without energy."),
                ("BIO101", "Cell biology", "A cell placed in a hypertonic solution will?", "Gain water and burst", "Lose water and shrink", "Remain unchanged", "Divide rapidly", "B", "Explanation: Water leaves the cell in a hypertonic solution, causing shrinkage."),
                ("BIO101", "Cell biology", "Which statement best explains selective permeability?", "All substances pass freely", "Only gases can pass", "Some substances can cross the membrane", "Only water crosses", "C", "Explanation: Cell membranes allow some substances to pass while restricting others."),
                ("BIO101", "Cell biology", "Which of the following requires membrane proteins but no ATP?", "Active transport", "Facilitated diffusion", "Endocytosis", "Exocytosis", "B", "Explanation: Facilitated diffusion uses proteins without energy input."),
                ("BIO101", "Cell biology", "Which process is responsible for uptake of large particles into a cell?", "Diffusion", "Osmosis", "Endocytosis", "Facilitated diffusion", "C", "Explanation: Endocytosis involves engulfing large particles into vesicles."),
                ("BIO101", "Cell biology", "Which of the following best defines osmosis?", "Movement of solute molecules", "Movement of water from high to low water potential", "Movement against gradient", "Movement using ATP", "B", "Explanation: Osmosis is the diffusion of water across a semi-permeable membrane."),
                ("BIO101", "Cell biology", "Which would increase the rate of diffusion across a membrane?", "Lower temperature", "Smaller surface area", "Steeper concentration gradient", "Thicker membrane", "C", "Explanation: A larger concentration gradient increases diffusion rate."),
                ("BIO101", "Cell biology", "Which cell component is directly responsible for maintaining internal balance?", "Cell membrane", "Nucleus", "Ribosome", "Mitochondria", "A", "Explanation: The membrane controls entry and exit of substances, maintaining homeostasis."),
                ("BIO101", "Cell biology", "Which of the following is TRUE about cells in an isotonic solution?", "They swell", "They shrink", "No net movement of water", "They burst", "C", "Explanation: In isotonic conditions, water moves equally in both directions."),
                ("BIO101", "Cell biology", "Which process would stop immediately if ATP production is inhibited?", "Diffusion", "Osmosis", "Active transport", "Facilitated diffusion", "C", "Explanation: Active transport depends directly on ATP."),
                ("BIO101", "Cell biology", "Which structure forms the basic framework of the cell membrane?", "Protein bilayer", "Phospholipid bilayer", "Carbohydrate layer", "Cellulose wall", "B", "Explanation: The membrane is primarily composed of a phospholipid bilayer."),
                ("BIO101", "Cell biology", "Which of the following is NOT a passive transport process?", "Diffusion", "Osmosis", "Facilitated diffusion", "Active transport", "D", "Explanation: Active transport requires energy, unlike passive processes."),
                ("BIO101", "Cell biology", "Which condition would cause red blood cells to burst?", "Hypertonic solution", "Isotonic solution", "Hypotonic solution", "Concentrated saline", "C", "Explanation: In hypotonic solution, water enters cells causing them to burst (lysis)."),
                ("BIO101", "Cell biology", "Which statement best links cell theory with membrane transport?", "Cells are static structures", "Cells exchange materials with their environment", "Cells do not need energy", "Cells lack organization", "B", "Explanation: Cell theory emphasizes that cells are dynamic and interact with their environment through transport mechanisms."),

                ("BIO101", "Cell biology", "Which statement best integrates cell theory with differences between prokaryotic and eukaryotic cells?", "All cells have identical internal structures", "Only eukaryotic cells are considered living", "All cells share basic features but differ in complexity", "Prokaryotes do not follow cell theory", "C", "Explanation: Cell theory states all living things are made of cells, but complexity differs between prokaryotes and eukaryotes."),
                ("BIO101", "Cell biology", "Which feature is unique to eukaryotic cells?", "DNA", "Cell membrane", "Membrane-bound nucleus", "Ribosomes", "C", "Explanation: Only eukaryotic cells have a true nucleus enclosed by a membrane."),
                ("BIO101", "Cell biology", "Which structure in prokaryotes performs a function analogous to the eukaryotic nucleus?", "Mitochondrion", "Nucleoid region", "Ribosome", "Cell wall", "B", "Explanation: The nucleoid region contains DNA in prokaryotes but is not membrane-bound."),
                ("BIO101", "Cell biology", "Which of the following organelles is correctly matched with its primary function?", "Ribosome – lipid synthesis", "Mitochondrion – ATP production", "Nucleus – protein digestion", "Golgi apparatus – DNA replication", "B", "Explanation: Mitochondria are responsible for ATP production via respiration."),
                ("BIO101", "Cell biology", "Which of the following is present in BOTH prokaryotic and eukaryotic cells?", "Nucleus", "Mitochondria", "Ribosomes", "Golgi apparatus", "C", "Explanation: Ribosomes are found in both cell types, although they differ in size."),
                ("BIO101", "Cell biology", "Which organelle would be most affected if a cell could no longer synthesize proteins?", "Mitochondria", "Nucleus", "Ribosome", "Lysosome", "C", "Explanation: Ribosomes are directly responsible for protein synthesis."),
                ("BIO101", "Cell biology", "Which statement about mitochondria supports the endosymbiotic theory?", "They lack membranes", "They have linear DNA", "They replicate independently within the cell", "They are formed in the Golgi apparatus", "C", "Explanation: Mitochondria can replicate independently, suggesting a prokaryotic origin."),
                ("BIO101", "Cell biology", "Which organelle is primarily responsible for regulating gene expression?", "Ribosome", "Nucleus", "Mitochondrion", "Golgi apparatus", "B", "Explanation: The nucleus controls gene expression by regulating DNA transcription."),
                ("BIO101", "Cell biology", "Which of the following is NOT found in prokaryotic cells?", "Plasma membrane", "Cytoplasm", "Membrane-bound organelles", "Ribosomes", "C", "Explanation: Prokaryotes lack membrane-bound organelles."),
                ("BIO101", "Cell biology", "Which of the following best explains why eukaryotic cells are generally larger?", "They lack DNA", "They have compartmentalization by organelles", "They do not carry out metabolism", "They lack ribosomes", "B", "Explanation: Membrane-bound organelles allow more complex and larger cell structures."),
                ("BIO101", "Cell biology", "Which organelle is responsible for packaging and secretion of proteins?", "Rough ER", "Golgi apparatus", "Smooth ER", "Nucleus", "B", "Explanation: The Golgi apparatus modifies and packages proteins for secretion."),
                ("BIO101", "Cell biology", "Which organelle contains enzymes for intracellular digestion?", "Ribosome", "Lysosome", "Nucleus", "Mitochondrion", "B", "Explanation: Lysosomes contain digestive enzymes."),
                ("BIO101", "Cell biology", "Which of the following best describes the cytoplasm?", "A rigid outer layer", "A fluid medium where organelles are suspended", "A storage site for DNA only", "A membrane-bound compartment", "B", "Explanation: Cytoplasm is the gel-like substance that holds organelles."),
                ("BIO101", "Cell biology", "Which structure is responsible for ribosome production?", "Golgi apparatus", "Nucleolus", "Mitochondrion", "Smooth ER", "B", "Explanation: The nucleolus synthesizes rRNA and assembles ribosomes."),
                ("BIO101", "Cell biology", "Which organelle is directly involved in detoxification processes?", "Rough ER", "Smooth ER", "Ribosome", "Nucleus", "B", "Explanation: Smooth ER detoxifies harmful substances and synthesizes lipids."),
                ("BIO101", "Cell biology", "Which statement about ribosomes is TRUE?", "They are absent in prokaryotes", "They are membrane-bound", "They are sites of protein synthesis", "They contain DNA", "C", "Explanation: Ribosomes synthesize proteins and are not membrane-bound."),
                ("BIO101", "Cell biology", "Which of the following would most directly affect ATP production?", "Damage to nucleus", "Damage to mitochondria", "Damage to ribosomes", "Damage to Golgi apparatus", "B", "Explanation: Mitochondria are responsible for ATP production."),
                ("BIO101", "Cell biology", "Which of the following best differentiates prokaryotic DNA from eukaryotic DNA?", "Prokaryotic DNA is linear", "Eukaryotic DNA is circular", "Prokaryotic DNA is circular and not membrane-bound", "Eukaryotic DNA is not in nucleus", "C", "Explanation: Prokaryotic DNA is typically circular and located in the nucleoid."),
                ("BIO101", "Cell biology", "Which organelle is most abundant in cells actively secreting proteins?", "Smooth ER", "Golgi apparatus", "Mitochondria", "Lysosomes", "B", "Explanation: Secretory cells have well-developed Golgi apparatus."),
                ("BIO101", "Cell biology", "Which statement best reflects the functional importance of organelles in eukaryotic cells?", "All organelles perform the same function", "Organelles allow specialization and efficiency", "Organelles are unnecessary", "Only one organelle is active at a time", "B", "Explanation: Organelles enable compartmentalization and specialization of cellular processes."),

                #Cell Divsion
                ("BIO101", "Cell Division", "Which phase of the cell cycle is characterized by DNA replication?", "G1 phase", "S phase", "G2 phase", "M phase", "B", "Explanation: DNA replication occurs during the S (synthesis) phase of interphase."),
                ("BIO101", "Cell Division", "Which stage of mitosis involves alignment of chromosomes at the equatorial plate?", "Prophase", "Metaphase", "Anaphase", "Telophase", "B", "Explanation: In metaphase, chromosomes align at the cell’s equator."),
                ("BIO101", "Cell Division", "Which of the following correctly describes anaphase of mitosis?", "Chromosomes condense", "Chromosomes line up at equator", "Sister chromatids separate", "Nuclear membrane reforms", "C", "Explanation: During anaphase, sister chromatids are pulled apart to opposite poles."),
                ("BIO101", "Cell Division", "Which event occurs during telophase?", "DNA replication", "Chromosome alignment", "Reformation of nuclear membrane", "Chromatid separation", "C", "Explanation: Telophase involves reformation of the nuclear envelope around chromosomes."),
                ("BIO101", "Cell Division", "Which of the following is a key difference between mitosis and meiosis?", "Mitosis produces haploid cells", "Meiosis produces genetically identical cells", "Mitosis produces two identical diploid cells", "Meiosis occurs in somatic cells", "C", "Explanation: Mitosis produces two identical diploid daughter cells."),
                ("BIO101", "Cell Division", "Which stage of meiosis involves crossing over?", "Prophase I", "Metaphase I", "Anaphase II", "Telophase II", "A", "Explanation: Crossing over occurs during prophase I, increasing genetic variation."),
                ("BIO101", "Cell Division", "Which of the following correctly describes meiosis II?", "It reduces chromosome number", "It is identical to mitosis", "It involves crossing over", "It produces diploid cells", "B", "Explanation: Meiosis II resembles mitosis, separating sister chromatids."),
                ("BIO101", "Cell Division", "Which of the following results from meiosis?", "Two identical diploid cells", "Four genetically identical cells", "Four genetically diverse haploid cells", "Two haploid identical cells", "C", "Explanation: Meiosis produces four genetically different haploid cells."),
                ("BIO101", "Cell Division", "Which stage ensures that each daughter cell receives identical genetic material in mitosis?", "Prophase", "Metaphase", "Anaphase", "Cytokinesis", "C", "Explanation: During anaphase, chromatids separate equally to ensure identical distribution."),
                ("BIO101", "Cell Division", "Which of the following is NOT part of interphase?", "G1 phase", "S phase", "G2 phase", "Prophase", "D", "Explanation: Prophase is part of mitosis, not interphase."),
                ("BIO101", "Cell Division", "Which of the following is the correct order of mitotic phases?", "Metaphase → Prophase → Anaphase → Telophase", "Prophase → Metaphase → Anaphase → Telophase", "Anaphase → Prophase → Telophase → Metaphase", "Prophase → Anaphase → Metaphase → Telophase", "B", "Explanation: The correct sequence is PMAT: Prophase, Metaphase, Anaphase, Telophase."),
                ("BIO101", "Cell Division", "Which of the following best describes cytokinesis?", "Division of nucleus", "Replication of DNA", "Division of cytoplasm", "Alignment of chromosomes", "C", "Explanation: Cytokinesis is the division of cytoplasm to form separate cells."),
