                ("BIO101", "Plant and Animal Biology(Intro level)", "Which vascular tissue transports water in plants?", "Phloem", "Xylem", "Cambium", "Cortex", "B", "Explanation: Xylem transports water and minerals from roots to other parts of the plant."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which vascular tissue transports food in plants?", "Xylem", "Phloem", "Cambium", "Epidermis", "B", "Explanation: Phloem transports manufactured food (sugars) throughout the plant."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which organelle is known as the control center of the cell?", "Ribosome", "Nucleus", "Golgi apparatus", "Lysosome", "B", "Explanation: The nucleus contains DNA and regulates cell activities."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which group of plants has true roots, stems, and leaves but no seeds?", "Bryophytes", "Pteridophytes", "Gymnosperms", "Angiosperms", "B", "Explanation: Pteridophytes (e.g., ferns) have vascular tissues but reproduce by spores."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which of the following is NOT a function of the cell membrane?", "Selective permeability", "Protection", "Photosynthesis", "Communication", "C", "Explanation: Photosynthesis occurs in chloroplasts, not the cell membrane."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which structure stores water and maintains turgor pressure in plant cells?", "Nucleus", "Central vacuole", "Mitochondrion", "Ribosome", "B", "Explanation: The large central vacuole helps maintain cell rigidity."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which classification group produces seeds enclosed within fruits?", "Gymnosperms", "Angiosperms", "Bryophytes", "Algae", "B", "Explanation: Angiosperms produce seeds enclosed in fruits."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which of the following is common to both plant and animal cells?", "Cell wall", "Chloroplast", "Cell membrane", "Large vacuole", "C", "Explanation: Both plant and animal cells have a cell membrane."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which cell organelle is responsible for energy production (ATP)?", "Nucleus", "Mitochondrion", "Ribosome", "Golgi apparatus", "B", "Explanation: Mitochondria generate ATP through cellular respiration."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which plant group is considered the simplest and mostly aquatic?", "Algae", "Bryophytes", "Gymnosperms", "Angiosperms", "A", "Explanation: Algae are simple, mostly aquatic organisms lacking true tissues."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which structure is responsible for packaging and transporting proteins?", "Ribosome", "Golgi apparatus", "Lysosome", "Nucleus", "B", "Explanation: The Golgi apparatus modifies and packages proteins for transport."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which of the following best describes animal cells compared to plant cells?", "They have cell walls", "They contain chloroplasts", "They lack a fixed shape", "They store starch", "C", "Explanation: Animal cells lack cell walls, giving them flexible shapes."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which plant structure is primarily responsible for gas exchange?", "Root hair", "Stomata", "Xylem", "Phloem", "B", "Explanation: Stomata regulate gas exchange in leaves."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which group of plants lacks vascular tissues and true roots?", "Bryophytes", "Pteridophytes", "Gymnosperms", "Angiosperms", "A", "Explanation: Bryophytes lack vascular tissues and true roots."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which of the following is a characteristic of gymnosperms?", "Flower production", "Fruit formation", "Naked seeds", "Spore reproduction only", "C", "Explanation: Gymnosperms produce seeds that are not enclosed in fruits."),
                ("BIO101", "Plant and Animal Biology(Intro level)", "Which organelle detoxifies harmful substances in cells?", "Ribosome", "Smooth endoplasmic reticulum", "Nucleus", "Vacuole", "B", "Explanation: The smooth ER is involved in detoxification processes."),

                #second semester course

                ("PHY102", "Electrostatics", "Two identical conducting spheres carry charges of +8 μC and -2 μC. They are brought into contact and separated. What is the final charge on each sphere?", "+3 μC", "+5 μC", "+6 μC", "-3 μC", "A", "Explanation: Total charge = +8 - 2 = +6 μC. Since the spheres are identical, the charge is shared equally. Each sphere gets +3 μC."),
                ("PHY102", "Electrostatics", "Which statement best illustrates the law of conservation of charge?", "Charge can be created by friction.", "The total charge of an isolated system remains constant.", "Positive charges are always greater than negative charges.", "Charges disappear when grounded.", "B", "Explanation: The law of conservation of charge states that charge cannot be created or destroyed, only transferred."),
                ("PHY102", "Electrostatics", "A positively charged rod is brought near an isolated neutral conductor without touching it. The conductor becomes polarized because", "electrons are created inside the conductor.", "positive charges move toward the rod.", "electrons redistribute within the conductor.", "the conductor gains positive charge from the rod.", "C", "Explanation: Polarization occurs because free electrons move toward the positively charged rod while positive ions remain fixed."),
                ("PHY102", "Electrostatics", "The electrostatic force between two charges is doubled when", "the distance between them is doubled.", "one charge is doubled while the other and distance remain unchanged.", "both charges are halved.", "the distance is increased by √2.", "B", "Explanation: Coulomb's law states F = kq₁q₂/r². Doubling one charge doubles the force."),
                ("PHY102", "Electrostatics", "Two charges are separated by a distance r. If both charges are doubled and the separation is also doubled, the new electrostatic force becomes", "4F", "2F", "F", "F/2", "C", "Explanation: F' = k(2q₁)(2q₂)/(2r)² = 4kq₁q₂/4r² = F."),
                ("PHY102", "Electrostatics", "At which location is the electric field due to a positive point charge greatest?", "Very close to the charge.", "At infinity.", "It is the same everywhere.", "Halfway between two neutral objects.", "A", "Explanation: Electric field intensity E = kQ/r², so it increases as the distance decreases."),
                ("PHY102", "Electrostatics", "A charge of +5 μC experiences a force of 0.20 N in an electric field. The field intensity is", "2.5 × 10⁴ N/C", "4.0 × 10⁴ N/C", "5.0 × 10⁴ N/C", "1.0 × 10⁵ N/C", "B", "Explanation: E = F/q = 0.20/(5×10⁻⁶) = 4.0 × 10⁴ N/C."),
                ("PHY102", "Electrostatics", "Which statement about electric field lines is correct?", "They may intersect at one point.", "They originate from negative charges and terminate on positive charges.", "Their density represents the strength of the electric field.", "They always form closed loops.", "C", "Explanation: The closer the field lines, the stronger the electric field. Field lines never intersect."),
                ("PHY102", "Electrostatics", "The electric potential at a point is zero. Which statement must be true?", "The electric field is also zero.", "No charge exists anywhere.", "The potential energy of every charge is zero.", "The electric field may still be non-zero.", "D", "Explanation: Zero electric potential does not necessarily imply zero electric field."),
                ("PHY102", "Electrostatics", "A positive charge moves naturally from point A to point B. Which statement is correct?", "Point B is at a higher electric potential than A.", "Point B is at a lower electric potential than A.", "The potential difference is zero.", "The electric field points from B to A.", "B", "Explanation: Positive charges move spontaneously from higher to lower electric potential."),
                ("PHY102", "Electrostatics", "Work done in moving a test charge between two points on the same equipotential surface is", "maximum.", "equal to the electric potential.", "zero.", "equal to the electric field intensity.", "C", "Explanation: There is no potential difference between points on an equipotential surface, so no work is done."),
                ("PHY102", "Electrostatics", "Electric field lines intersect equipotential surfaces at", "45°", "0°", "90°", "180°", "C", "Explanation: Electric field lines are always perpendicular to equipotential surfaces."),
                ("PHY102", "Electrostatics", "The electric dipole moment is directed", "from negative to positive charge.", "from positive to negative charge.", "toward the stronger charge.", "perpendicular to the dipole axis.", "A", "Explanation: By convention, dipole moment points from the negative charge toward the positive charge."),
                ("PHY102", "Electrostatics", "The net electric field at the midpoint of an electric dipole is directed", "toward the positive charge.", "from positive to negative charge.", "from negative to positive charge.", "zero.", "C", "Explanation: The fields due to the two charges add in the same direction at the midpoint, pointing from negative to positive."),
                ("PHY102", "Electrostatics", "For a uniformly charged solid sphere, Gauss's law predicts that the electric field outside the sphere behaves as if", "all the charge were concentrated at the center.", "the charge were uniformly spread throughout space.", "there were no charge inside.", "the field were constant everywhere.", "A", "Explanation: Outside a uniformly charged sphere, the field is identical to that of a point charge located at the center."),
                ("PHY102", "Electrostatics", "According to Gauss's law, if the net electric flux through a closed surface is zero, then", "the electric field is zero everywhere on the surface.", "there are no charges anywhere near the surface.", "the net enclosed charge is zero.", "the surface must be spherical.", "C", "Explanation: Zero net electric flux implies the algebraic sum of enclosed charges is zero."),
                ("PHY102", "Electrostatics", "An infinitely long uniformly charged wire is best analyzed using a", "spherical Gaussian surface.", "cylindrical Gaussian surface.", "cubical Gaussian surface.", "hemispherical Gaussian surface.", "B", "Explanation: Cylindrical symmetry makes the cylindrical Gaussian surface the correct choice."),
                ("PHY102", "Electrostatics", "The electric field inside a hollow conducting sphere in electrostatic equilibrium is", "greatest at the center.", "uniform but non-zero.", "equal to the surface field.", "zero everywhere.", "D", "Explanation: A fundamental result from Gauss's law is that the electric field inside a conductor in electrostatic equilibrium is zero."),
                ("PHY102", "Electrostatics", "A continuous charge distribution differs from a collection of discrete point charges because it is described by", "only Coulomb's constant.", "charge density and integration over the distribution.", "Newton's laws of motion.", "electric potential only.", "B", "Explanation: Continuous charge distributions require linear, surface, or volume charge density and integration to determine the field or potential."),
                ("PHY102", "Electrostatics", "A closed Gaussian surface encloses charges +5 C, -3 C and -4 C. The net electric flux through the surface is", "+2/ε₀", "-2/ε₀", "+12/ε₀", "Zero", "B", "Explanation: Net enclosed charge = +5 - 3 - 4 = -2 C. By Gauss's law, Φ = Q_enclosed/ε₀ = -2/ε₀."),

                ("PHY102", "Electrostatics", "A glass rod rubbed with silk becomes positively charged because", "Protons move from the glass to the silk.", "Electrons move from the silk to the glass.", "Electrons move from the glass to the silk.", "Neutrons move from the glass to the silk.", "C", "Explanation: The glass loses electrons to the silk, leaving the glass positively charged."),
                ("PHY102", "Electrostatics", "Three identical conducting spheres carry charges of +12 μC, -6 μC, and +3 μC. They are brought into contact simultaneously and then separated. What is the charge on each sphere?", "+3 μC", "+4 μC", "+5 μC", "+6 μC", "A", "Explanation: Total charge = +12 - 6 + 3 = +9 μC. Dividing equally among three identical spheres gives +3 μC each."),
                ("PHY102", "Electrostatics", "Two point charges repel each other with a force F. If the distance between them is reduced to one-third of its original value, the new force is", "3F", "6F", "9F", "F/9", "C", "Explanation: Coulomb's law states F ∝ 1/r². Reducing the distance to one-third increases the force by 3² = 9."),
                ("PHY102", "Electrostatics", "Which quantity is a vector?", "Electric potential", "Potential difference", "Electric field intensity", "Electric potential energy", "C", "Explanation: Electric field intensity has both magnitude and direction, making it a vector quantity."),
                ("PHY102", "Electrostatics", "A negative test charge placed in an electric field experiences a force", "In the direction of the electric field.", "Opposite to the direction of the electric field.", "Perpendicular to the electric field.", "Independent of the electric field.", "B", "Explanation: The electric field direction is defined as the force on a positive test charge. A negative charge experiences force in the opposite direction."),
                ("PHY102", "Electrostatics", "Which of the following is NOT a method of charging an object?", "Conduction", "Induction", "Friction", "Magnetization", "D", "Explanation: Objects are charged by friction, conduction, or induction. Magnetization does not produce electric charge."),
                ("PHY102", "Electrostatics", "If the electric field at a point is zero, the electric potential at that point", "Must also be zero.", "Must be positive.", "May have any constant value.", "Must be negative.", "C", "Explanation: Zero electric field means the potential is not changing at that point. The potential itself can be any constant value."),
                ("PHY102", "Electrostatics", "The SI unit of electric field intensity is", "Volt", "Newton per Coulomb", "Coulomb per Newton", "Joule per Coulomb", "B", "Explanation: Electric field intensity is measured in N/C, which is equivalent to V/m."),
                ("PHY102", "Electrostatics", "A charge of 4 C passes through a potential difference of 15 V. The work done is", "3.75 J", "19 J", "60 J", "120 J", "C", "Explanation: Work done W = qV = 4 × 15 = 60 J."),
                ("PHY102", "Electrostatics", "Electric field lines around an isolated negative charge are directed", "Away from the charge.", "Toward the charge.", "Tangential to the charge.", "Randomly.", "B", "Explanation: Electric field lines terminate on negative charges."),
                ("PHY102", "Electrostatics", "The electric flux through a closed surface depends directly on", "The total electric field outside the surface.", "The area of the surface only.", "The net charge enclosed by the surface.", "The shape of the surface.", "C", "Explanation: According to Gauss's law, electric flux depends only on the net enclosed charge."),
                ("PHY102", "Electrostatics", "Which Gaussian surface is most suitable for calculating the electric field of an infinite plane sheet of charge?", "Cube", "Cylinder", "Sphere", "Cone", "B", "Explanation: A cylindrical Gaussian surface (pillbox) exploits the symmetry of an infinite plane sheet."),
                ("PHY102", "Electrostatics", "For a positively charged conducting sphere in electrostatic equilibrium, excess charge resides", "Uniformly throughout the volume.", "At the center only.", "On the outer surface.", "Only on the lower half.", "C", "Explanation: Free charges move until they reside entirely on the outer surface of the conductor."),
                ("PHY102", "Electrostatics", "The electric potential due to a point charge varies with distance as", "1/r²", "1/r", "r²", "r", "B", "Explanation: Electric potential due to a point charge is V = kQ/r."),
                ("PHY102", "Electrostatics", "Two equal positive charges are fixed in space. At the midpoint between them, the electric field is", "Maximum.", "Equal to that due to one charge.", "Zero.", "Directed toward one of the charges.", "C", "Explanation: The electric fields are equal in magnitude and opposite in direction, so they cancel."),
                ("PHY102", "Electrostatics", "A dipole is placed in a uniform electric field. If its dipole moment is parallel to the field, the torque acting on it is", "Maximum.", "Zero.", "Equal to the electric field intensity.", "Independent of the field.", "B", "Explanation: Torque τ = pE sinθ. When θ = 0°, sinθ = 0, so the torque is zero."),
                ("PHY102", "Electrostatics", "Which of the following is true for electrostatic equilibrium inside a conductor?", "Electric field is maximum.", "Electric potential varies linearly.", "Electric field is zero and potential is constant.", "Electric potential is zero everywhere.", "C", "Explanation: Inside a conductor at electrostatic equilibrium, the electric field is zero and the potential is constant."),
                ("PHY102", "Electrostatics", "The linear charge density λ is defined as", "Charge per unit area.", "Charge per unit length.", "Charge per unit volume.", "Force per unit charge.", "B", "Explanation: Linear charge density λ = Q/L and is measured in C/m."),
                ("PHY102", "Electrostatics", "If the enclosed charge inside a Gaussian surface is doubled while the surface remains unchanged, the electric flux becomes", "Half its original value.", "Unchanged.", "Twice its original value.", "Four times its original value.", "C", "Explanation: From Gauss's law, Φ = Q/ε₀. Doubling the enclosed charge doubles the electric flux."),
                ("PHY102", "Electrostatics", "Which statement correctly distinguishes electric field from electric potential?", "Both are vector quantities.", "Electric field is scalar while electric potential is vector.", "Electric field is the gradient of electric potential, while electric potential is a scalar.", "Electric potential always points in the direction of the electric field.", "C", "Explanation: Electric potential is a scalar quantity, while the electric field is a vector equal to the negative gradient of the potential."),

                ("PHY102", "Electrostatics", "Two identical metallic spheres carry charges +12 μC and -4 μC respectively. After touching and separating, one sphere is grounded. What is the final charge on the grounded sphere?", "0 μC", "+4 μC", "-4 μC", "+8 μC", "A", "Explanation: After contact, each sphere has (+12 - 4)/2 = +4 μC. Grounding allows excess positive charge to flow to Earth, leaving the sphere neutral."),
                ("PHY102", "Electrostatics", "A charge q experiences an electric force F in vacuum. If the medium is replaced with one of relative permittivity 4 while all other quantities remain unchanged, the new force is", "F", "F/2", "F/4", "4F", "C", "Explanation: Coulomb's force in a medium is reduced by the dielectric constant. F' = F/4."),
                ("PHY102", "Electrostatics", "Which of the following statements about electric field lines is FALSE?", "They originate from positive charges.", "They terminate on negative charges.", "They intersect where the electric field is strongest.", "Their density is proportional to field strength.", "C", "Explanation: Electric field lines never intersect because the electric field has only one direction at any point."),
                ("PHY102", "Electrostatics", "A positive charge is moved around a closed path in an electrostatic field. The total work done by the electric field is", "Positive.", "Negative.", "Zero.", "Equal to qV.", "C", "Explanation: Electrostatic fields are conservative; therefore, the net work over any closed path is zero."),
                ("PHY102", "Electrostatics", "A hollow conducting sphere carries excess charge. The electric field at every point inside the hollow cavity is", "Maximum.", "Zero if no charge is inside the cavity.", "Equal to the surface field.", "Constant but non-zero.", "B", "Explanation: Electrostatic shielding ensures the electric field inside an empty cavity is zero."),
                ("PHY102", "Electrostatics", "If the electric field at a point is zero, which statement must always be true?", "The electric potential is zero.", "The electric force on any charge is zero.", "The potential is maximum.", "No charges exist nearby.", "B", "Explanation: Since F = qE, zero electric field means no electric force on a charge placed there. Potential need not be zero."),
                ("PHY102", "Electrostatics", "A charge is placed exactly midway between two identical positive charges. The electric field at the midpoint is", "Maximum.", "Directed toward either charge.", "Zero.", "Infinite.", "C", "Explanation: Equal and opposite electric fields cancel at the midpoint."),
                ("PHY102", "Electrostatics", "The electric potential at infinity is conventionally taken as", "1 V", "Dependent on the charge.", "Zero.", "Infinite.", "C", "Explanation: Electric potential is defined to be zero at infinity for isolated charge systems."),
                ("PHY102", "Electrostatics", "Which Gaussian surface is most appropriate for determining the electric field due to an infinitely long charged cylinder?", "Cube", "Sphere", "Cylinder", "Cone", "C", "Explanation: The cylindrical symmetry of the charge distribution makes a cylindrical Gaussian surface appropriate."),
                ("PHY102", "Electrostatics", "The electric field immediately outside the surface of a charged conductor is", "Always zero.", "Parallel to the surface.", "Perpendicular to the surface.", "Independent of charge density.", "C", "Explanation: Electric field lines leave the surface normally; otherwise, charges would move along the surface."),
                ("PHY102", "Electrostatics", "The torque on an electric dipole is greatest when the angle between the dipole moment and the electric field is", "0°", "30°", "90°", "180°", "C", "Explanation: τ = pE sinθ, which is maximum when θ = 90°."),
                ("PHY102", "Electrostatics", "Which quantity remains constant everywhere inside a conductor in electrostatic equilibrium?", "Electric field", "Charge density", "Electric potential", "Electric flux", "C", "Explanation: The entire conductor is an equipotential region."),
                ("PHY102", "Electrostatics", "An electron moves from a point of lower potential to a point of higher potential. Its electric potential energy", "Increases.", "Decreases.", "Remains constant.", "Becomes zero.", "B", "Explanation: U = qV. Since q is negative, increasing V decreases potential energy."),
                ("PHY102", "Electrostatics", "A Gaussian surface encloses +10 C and -6 C. Another +8 C charge lies outside the surface. The net electric flux is", "12/ε₀", "4/ε₀", "18/ε₀", "-4/ε₀", "B", "Explanation: Only enclosed charges contribute. Net enclosed charge = +4 C."),
                ("PHY102", "Electrostatics", "A charged particle released from rest moves in the same direction as the electric field. The particle is", "Positive.", "Negative.", "Neutral.", "Cannot be determined.", "A", "Explanation: Positive charges accelerate in the direction of the electric field."),
                ("PHY102", "Electrostatics", "Which statement correctly compares electric potential and electric field?", "Both are vector quantities.", "Potential is scalar while electric field is vector.", "Potential is vector while electric field is scalar.", "Both are scalar quantities.", "B", "Explanation: Electric potential has magnitude only, whereas electric field has both magnitude and direction."),
                ("PHY102", "Electrostatics", "The electric field inside a uniformly charged solid conducting sphere is", "Zero everywhere.", "Proportional to r.", "Inversely proportional to r².", "Constant everywhere.", "A", "Explanation: In a conductor under electrostatic equilibrium, the electric field inside is zero."),
                ("PHY102", "Electrostatics", "Two equal but opposite charges are separated by a fixed distance. At a point very far away from the charges, the electric potential is approximately", "Infinite.", "Zero.", "Equal to kQ/r.", "Maximum.", "B", "Explanation: At large distances, the potentials due to the positive and negative charges nearly cancel."),
                ("PHY102", "Electrostatics", "If the electric flux through every possible closed surface in a region is zero, the region must contain", "No electric field.", "No net enclosed charge.", "No electric potential.", "Only positive charges.", "B", "Explanation: By Gauss's law, zero net flux through any closed surface implies zero enclosed charge."),
                ("PHY102", "Electrostatics", "A proton and an electron are placed in the same uniform electric field. Neglecting gravity, which statement is correct?", "They experience equal forces in opposite directions.", "The proton experiences the larger force.", "The electron experiences the larger force.", "Both move in the same direction.", "A", "Explanation: Since both have charges of equal magnitude, F = qE gives equal force magnitudes but opposite directions."),

                ("PHY102", "Electrostatics", "A point charge is placed at the exact center of a spherical Gaussian surface. If the radius of the sphere is doubled, the total electric flux through the sphere becomes", "Twice its original value.", "Half its original value.", "Four times its original value.", "Unchanged.", "D", "Explanation: By Gauss's law, the total electric flux depends only on the enclosed charge, not on the size of the Gaussian surface."),
                ("PHY102", "Electrostatics", "Two identical positive charges are fixed a distance 2d apart. At what point along the line joining them is the electric potential zero?", "At the midpoint.", "At a distance d from either charge.", "At infinity only.", "There is no finite point where the potential is zero.", "D", "Explanation: The potential due to each positive charge is positive, so their sum is always positive at every finite point."),
                ("PHY102", "Electrostatics", "A charged particle is released from rest at a point where the electric potential is zero. Which statement is necessarily true?", "The electric field at that point is zero.", "The particle experiences no force.", "Its potential energy is zero only if the reference potential is chosen there.", "None of the above.", "D", "Explanation: A point may have zero potential but a non-zero electric field. Potential depends on the chosen reference."),
                ("PHY102", "Electrostatics", "A conductor contains a hollow cavity with no charge inside it. An external electric field is applied. The electric field inside the cavity is", "Equal to the external field.", "Greater than the external field.", "Zero.", "Dependent on the size of the cavity.", "C", "Explanation: Electrostatic shielding ensures that the electric field inside an empty cavity of a conductor is zero."),
                ("PHY102", "Electrostatics", "The electric field due to an infinite plane sheet of charge does NOT decrease with distance because", "The sheet has infinite charge.", "The increase in enclosed charge exactly compensates for the increase in Gaussian surface area.", "Coulomb's law does not apply.", "The electric field lines are circular.", "B", "Explanation: Applying Gauss's law to a pillbox Gaussian surface shows the field is constant and independent of distance."),
                ("PHY102", "Electrostatics", "A charge +Q is uniformly distributed over the surface of a conducting sphere. Another charge +q is placed inside the hollow cavity without touching the conductor. The charge induced on the inner surface of the conductor is", "+q", "-q", "+Q", "-Q", "B", "Explanation: A charge equal in magnitude and opposite in sign is induced on the inner surface to keep the electric field inside the conductor zero."),
                ("PHY102", "Electrostatics", "Which statement is TRUE for both electric field lines and equipotential surfaces?", "They are always parallel.", "They can intersect each other.", "They are always perpendicular to one another.", "They both represent vector quantities.", "C", "Explanation: Electric field lines are everywhere perpendicular to equipotential surfaces."),
                ("PHY102", "Electrostatics", "A positive point charge is surrounded by two concentric spherical Gaussian surfaces of radii r and 3r. The ratio of the total electric flux through the smaller sphere to that through the larger sphere is", "1 : 3", "1 : 9", "3 : 1", "1 : 1", "D", "Explanation: Both surfaces enclose the same charge, so Gauss's law gives the same total electric flux through each."),
                ("PHY102", "Electrostatics", "An electric dipole is placed in a non-uniform electric field. Which statement is correct?", "It experiences torque only.", "It experiences force only.", "It may experience both a net force and a torque.", "It experiences neither force nor torque.", "C", "Explanation: Unlike a uniform field, a non-uniform electric field can produce both a net force and a torque on a dipole."),
                ("PHY102", "Electrostatics", "Which of the following quantities is always conserved during any electrostatic charging process?", "Electric potential", "Electric field intensity", "Total electric charge", "Electric potential difference", "C", "Explanation: Charge may be transferred from one body to another, but the total electric charge of an isolated system remains constant."),

                ("PHY102", "Electric Field & Electric Potential", "Two equal positive charges are separated by a distance d. At the midpoint between them, the electric field is", "Maximum", "Zero", "Directed toward either charge", "Infinite", "B", "Explanation: The electric fields due to the two equal positive charges are equal in magnitude and opposite in direction, so they cancel."),
                ("PHY102", "Electric Field & Electric Potential", "Two equal positive charges are separated by a distance d. At the midpoint between them, the electric potential is", "Zero", "Negative", "Positive and non-zero", "Infinite", "C", "Explanation: Electric potential is a scalar quantity, so the potentials from both charges add instead of canceling."),
                ("PHY102", "Electric Field & Electric Potential", "A region has zero electric field. Which statement must always be true?", "The electric potential is zero.", "The electric potential is constant throughout the region.", "No charges exist anywhere nearby.", "The electric potential is maximum.", "B", "Explanation: Since E = -dV/dx, zero electric field means the potential does not change within that region."),
                ("PHY102", "Electric Field & Electric Potential", "Which of the following correctly relates electric field intensity E and electric potential V?", "E = dV/dr", "E = V/r always", "E = -dV/dr", "E = V²/r", "C", "Explanation: Electric field is the negative gradient of electric potential."),
                ("PHY102", "Electric Field & Electric Potential", "The electric field lines around an isolated positive charge", "Point toward the charge.", "Form concentric circles.", "Radiate outward from the charge.", "Are parallel straight lines.", "C", "Explanation: Electric field lines always originate from positive charges and terminate on negative charges."),
                ("PHY102", "Electric Field & Electric Potential", "If electric field lines become closer together in a region, it indicates that", "The electric potential is zero.", "The electric field is stronger.", "The electric field is weaker.", "The potential difference is zero.", "B", "Explanation: The density of electric field lines represents the magnitude of the electric field."),
                ("PHY102", "Electric Field & Electric Potential", "A positive charge moves naturally in the direction of the electric field because", "Electric potential increases.", "Its potential energy decreases.", "The field does positive work while potential decreases.", "Both B and C.", "D", "Explanation: Positive charges move toward lower potential, losing potential energy while the electric field does positive work."),
                ("PHY102", "Electric Field & Electric Potential", "A negative charge released from rest in an electric field moves toward", "Lower electric potential.", "Higher electric potential.", "A point where the electric field is zero only.", "The nearest positive charge only.", "B", "Explanation: Negative charges move opposite the electric field, toward higher electric potential."),
                ("PHY102", "Electric Field & Electric Potential", "Which statement about electric field lines is FALSE?", "They never intersect.", "They begin on positive charges.", "They always form closed loops.", "They are perpendicular to equipotential surfaces.", "C", "Explanation: Electric field lines do not form closed loops in electrostatics."),
                ("PHY102", "Electric Field & Electric Potential", "An electron moves from point A to point B. The electric potential increases by 20 V. The change in the electron's potential energy is", "+20 eV", "-20 eV", "Zero", "Cannot be determined", "B", "Explanation: ΔU = qΔV. Since the electron has a negative charge, its potential energy decreases when potential increases."),
                ("PHY102", "Electric Field & Electric Potential", "Which quantity determines the direction of the electric field at a point?", "The direction of force on a positive test charge.", "The direction of force on a negative test charge.", "The direction of motion of electrons.", "The electric potential only.", "A", "Explanation: Electric field direction is defined as the direction of the force on a positive test charge."),
                ("PHY102", "Electric Field & Electric Potential", "Two points lie on the same equipotential surface. Which quantity is necessarily zero?", "Electric field", "Electric force", "Potential difference", "Electric potential", "C", "Explanation: Every point on an equipotential surface has the same electric potential."),
                ("PHY102", "Electric Field & Electric Potential", "If a charge moves along an equipotential surface, the work done by the electric field is", "Positive.", "Negative.", "Maximum.", "Zero.", "D", "Explanation: W = qΔV. Since ΔV = 0, no work is done."),
                ("PHY102", "Electric Field & Electric Potential", "The SI unit of electric potential can also be written as", "N/C", "J/C", "C/J", "N·m/C²", "B", "Explanation: One volt equals one joule per coulomb."),
                ("PHY102", "Electric Field & Electric Potential", "The electric field at a point is 400 N/C. What force acts on a +5 μC charge placed there?", "0.002 N", "0.020 N", "2.0 N", "0.0002 N", "A", "Explanation: F = qE = (5 × 10⁻⁶)(400) = 2 × 10⁻³ N."),
                ("PHY102", "Electric Field & Electric Potential", "At which point is the electric potential due to a positive point charge greatest?", "At infinity.", "Closest to the charge.", "Halfway between two charges.", "Where the electric field is zero.", "B", "Explanation: V = kQ/r. Potential increases as the distance decreases."),
                ("PHY102", "Electric Field & Electric Potential", "A uniform electric field exists between two parallel plates. Which statement is correct?", "The electric field varies with distance.", "Electric field lines diverge.", "Equipotential surfaces are parallel to the plates.", "The electric potential is the same everywhere.", "C", "Explanation: In a uniform field, equipotential surfaces are parallel to the plates and perpendicular to the field."),
                ("PHY102", "Electric Field & Electric Potential", "Electric field intensity is numerically equal to the", "Potential difference per unit distance in the direction of the field.", "Potential multiplied by charge.", "Force multiplied by distance.", "Charge divided by potential.", "A", "Explanation: For a uniform field, E = V/d."),
                ("PHY102", "Electric Field & Electric Potential", "Which statement best explains why electric potential is a scalar quantity?", "It has only magnitude and no direction.", "It acts only on positive charges.", "It is measured in volts.", "It is independent of electric fields.", "A", "Explanation: Electric potential is completely described by magnitude without requiring direction."),
                ("PHY102", "Electric Field & Electric Potential", "A particle moves from a point of 120 V to a point of 60 V. If its charge is +3 C, the work done by the electric field is", "60 J", "180 J", "-180 J", "360 J", "B", "Explanation: W = q(V₁ - V₂) = 3 × (120 - 60) = 180 J. The electric field does positive work as the positive charge moves to lower potential."),

                ("PHY102", "Capacitance & Current Electricity", "A conductor differs from an insulator because a conductor has", "More protons than electrons", "Free electrons that can move throughout the material", "No electric field inside it", "A higher electric potential", "B", "Explanation: Conductors contain free electrons that move easily under an electric field, whereas insulators do not."),
                ("PHY102", "Capacitance & Current Electricity", "A capacitor stores", "Electric current", "Electric charge and electrical energy", "Only electric potential", "Magnetic energy only", "B", "Explanation: A capacitor stores equal and opposite charges on its plates and energy in the electric field between them."),
                ("PHY102", "Capacitance & Current Electricity", "The capacitance of a capacitor depends primarily on", "The charge stored on the plates", "The potential difference across the plates", "Its geometry and dielectric material", "The current flowing through it", "C", "Explanation: Capacitance depends on plate area, plate separation, and the dielectric constant."),
                ("PHY102", "Capacitance & Current Electricity", "If the separation between the plates of a parallel-plate capacitor is doubled while all other factors remain constant, its capacitance becomes", "Twice the original value", "Half the original value", "Four times the original value", "Unchanged", "B", "Explanation: For a parallel-plate capacitor, C = εA/d. Doubling d halves the capacitance."),
                ("PHY102", "Capacitance & Current Electricity", "A dielectric is inserted completely between the plates of an isolated charged capacitor. Which quantity remains constant?", "Capacitance", "Potential difference", "Electric field", "Charge", "D", "Explanation: Since the capacitor is isolated, charge cannot leave or enter, so it remains constant."),
                ("PHY102", "Capacitance & Current Electricity", "When a dielectric is inserted into a capacitor connected to a battery, the stored charge", "Decreases", "Remains constant", "Increases", "Becomes zero", "C", "Explanation: The battery maintains constant voltage, so the increased capacitance causes more charge to be stored."),
                ("PHY102", "Capacitance & Current Electricity", "Three identical capacitors each of capacitance C are connected in series. Their equivalent capacitance is", "3C", "C", "C/3", "C/9", "C", "Explanation: For three equal capacitors in series, Ceq = C/3."),
                ("PHY102", "Capacitance & Current Electricity", "Three identical capacitors each of capacitance C are connected in parallel. Their equivalent capacitance is", "C/3", "3C", "C", "9C", "B", "Explanation: Capacitances add directly in parallel, giving Ceq = 3C."),
                ("PHY102", "Capacitance & Current Electricity", "Which quantity is the same for all capacitors connected in series?", "Charge", "Voltage", "Capacitance", "Energy", "A", "Explanation: Every capacitor in a series combination carries the same charge."),
                ("PHY102", "Capacitance & Current Electricity", "Which quantity is common to all capacitors connected in parallel?", "Charge", "Energy", "Voltage", "Capacitance", "C", "Explanation: Each capacitor connected in parallel has the same potential difference."),
                ("PHY102", "Capacitance & Current Electricity", "The energy stored in a capacitor is best expressed as", "½CV²", "CV", "QV", "V²/C", "A", "Explanation: The energy stored is U = ½CV² = ½QV = Q²/(2C)." ),
                ("PHY102", "Capacitance & Current Electricity", "A 6 μF capacitor is charged to 12 V. The charge stored is", "72 μC", "2 μC", "0.5 μC", "18 μC", "A", "Explanation: Q = CV = 6 μF × 12 V = 72 μC."),
                ("PHY102", "Current Electricity", "Electric current is defined as the rate of flow of", "Voltage", "Resistance", "Electric charge", "Power", "C", "Explanation: Current is the amount of charge flowing per unit time, I = Q/t."),
                ("PHY102", "Current Electricity", "One ampere is equivalent to", "1 coulomb per second", "1 volt per coulomb", "1 joule per coulomb", "1 watt per second", "A", "Explanation: By definition, 1 A = 1 C/s."),
                ("PHY102", "Current Electricity", "Conventional current flows", "From negative to positive terminal", "In the direction of electron flow", "From positive to negative terminal", "Only through conductors", "C", "Explanation: Conventional current is defined as flowing from the positive terminal to the negative terminal."),
                ("PHY102", "Current Electricity", "If the charge passing through a conductor doubles while the time taken also doubles, the current will", "Double", "Be halved", "Remain unchanged", "Become four times larger", "C", "Explanation: Since I = Q/t, doubling both Q and t leaves the current unchanged."),
                ("PHY102", "Current Electricity", "Which graph represents Ohm's law for an ohmic conductor?", "A curved graph through the origin", "A straight line through the origin", "A horizontal line", "A vertical line", "B", "Explanation: Ohm's law states that current is directly proportional to voltage, producing a straight line through the origin."),
                ("PHY102", "Current Electricity", "A battery maintains a constant potential difference across a capacitor. If the plate area is doubled while the plate separation remains unchanged, the stored energy becomes", "Half its original value", "Twice its original value", "Four times its original value", "Unchanged", "B", "Explanation: Doubling the plate area doubles the capacitance. Since U = ½CV² and V is constant, the energy also doubles."),
                ("PHY102", "Capacitance & Current Electricity", "Two capacitors of 4 μF and 12 μF are connected in series. The equivalent capacitance is", "16 μF", "3 μF", "8 μF", "6 μF", "B", "Explanation: Ceq = (4 × 12)/(4 + 12) = 48/16 = 3 μF."),
                ("PHY102", "Capacitance & Current Electricity", "Two capacitors of 4 μF and 12 μF are connected in parallel across a battery. Which statement is correct?", "Both store the same charge.", "The 12 μF capacitor stores three times the charge of the 4 μF capacitor.", "The 4 μF capacitor stores more charge.", "Their voltages are different.", "B", "Explanation: Capacitors in parallel have the same voltage. Since Q = CV, the 12 μF capacitor stores three times the charge of the 4 μF capacitor."),

                ("PHY102", "Capacitance & Current Electricity", "A capacitor is connected to a battery and fully charged. If the battery is disconnected and the plate separation is increased, the potential difference across the capacitor will", "Decrease", "Remain constant", "Increase", "Become zero", "C", "Explanation: With the battery disconnected, charge remains constant. Since C decreases when plate separation increases, V = Q/C increases."),
                ("PHY102", "Capacitance & Current Electricity", "Which statement is TRUE for an ideal capacitor connected to a DC source after a long time?", "It behaves like a short circuit.", "It behaves like an open circuit.", "Current through it is maximum.", "Voltage across it becomes zero.", "B", "Explanation: After being fully charged, an ideal capacitor blocks DC current and behaves as an open circuit."),
                ("PHY102", "Capacitance & Current Electricity", "The dielectric constant of a material is always", "Less than 1", "Equal to 0", "Greater than or equal to 1", "Negative", "C", "Explanation: A dielectric constant is always at least 1, with vacuum having a value of exactly 1."),
                ("PHY102", "Capacitance & Current Electricity", "Two capacitors of 6 μF and 3 μF are connected in series across 18 V. The voltage across the 3 μF capacitor is", "6 V", "9 V", "12 V", "18 V", "C", "Explanation: In series, both capacitors carry the same charge. The smaller capacitor has the larger voltage. Ceq = 2 μF, Q = 36 μC, so V = Q/C = 36/3 = 12 V."),
                ("PHY102", "Capacitance & Current Electricity", "Two capacitors of 6 μF and 3 μF are connected in parallel across 18 V. The charge stored on the 6 μF capacitor is", "18 μC", "36 μC", "72 μC", "108 μC", "D", "Explanation: Q = CV = 6 μF × 18 V = 108 μC."),
                ("PHY102", "Capacitance & Current Electricity", "If the voltage across a capacitor is doubled while its capacitance remains constant, the energy stored becomes", "Twice as much", "Four times as much", "Half as much", "Unchanged", "B", "Explanation: Since U = ½CV², doubling the voltage increases the energy by a factor of four."),
                ("PHY102", "Capacitance & Current Electricity", "A capacitor initially stores energy U. If its stored charge is doubled while the capacitance remains constant, the new energy becomes", "2U", "4U", "U/2", "8U", "B", "Explanation: Since U = Q²/(2C), doubling the charge increases the energy by four."),
                ("PHY102", "Current Electricity", "Which of the following materials is the best electrical insulator?", "Copper", "Silver", "Glass", "Aluminium", "C", "Explanation: Glass has very few free electrons and is therefore an excellent insulator."),
                ("PHY102", "Current Electricity", "The drift velocity of electrons in a conductor is", "The speed of light", "Much smaller than the random thermal speed of electrons", "Equal to the applied voltage", "Independent of the electric field", "B", "Explanation: Drift velocity is extremely small compared to the random thermal motion of electrons."),
                ("PHY102", "Current Electricity", "If the current through a conductor is 4 A, the number of coulombs passing a cross-section in 30 s is", "7.5 C", "34 C", "120 C", "240 C", "C", "Explanation: Q = It = 4 × 30 = 120 C."),
                ("PHY102", "Current Electricity", "An electric current exists in a conductor because", "Electrons move with a net drift under an electric field", "Electrons move randomly", "Protons move through the wire", "Neutrons carry charge", "A", "Explanation: Current results from the net drift of electrons due to the applied electric field."),
                ("PHY102", "Current Electricity", "The direction of electron flow in a metallic conductor is", "The same as conventional current", "Opposite to conventional current", "Always upward", "Random", "B", "Explanation: Electrons move from the negative terminal to the positive terminal, opposite to conventional current."),
                ("PHY102", "Current Electricity", "If no potential difference exists across a conductor, the net drift current is", "Maximum", "Zero", "Infinite", "Dependent on temperature only", "B", "Explanation: Without a potential difference, there is no electric field to produce a net drift of electrons."),
                ("PHY102", "Current Electricity", "Current is measured using an ammeter connected", "In parallel with the component", "In series with the component", "Across the battery only", "In any convenient position", "B", "Explanation: An ammeter measures the current flowing through a circuit and must therefore be connected in series."),
                ("PHY102", "Capacitance & Current Electricity", "Which statement about capacitors connected in series is FALSE?", "The charge on each capacitor is the same.", "The equivalent capacitance is less than the smallest capacitor.", "The voltages across the capacitors are always equal.", "The total voltage equals the sum of individual voltages.", "C", "Explanation: In series, voltages are generally different unless the capacitances are equal."),
                ("PHY102", "Capacitance & Current Electricity", "Which statement about capacitors connected in parallel is FALSE?", "The voltage across each capacitor is the same.", "The equivalent capacitance is the sum of all capacitances.", "The charge on every capacitor must be equal.", "The total stored charge equals the sum of individual charges.", "C", "Explanation: In parallel, voltages are equal, but charges depend on the capacitance of each capacitor."),
                ("PHY102", "Capacitance & Current Electricity", "A charged capacitor is disconnected from its battery. Inserting a dielectric causes the electric field between the plates to", "Increase", "Remain unchanged", "Decrease", "Become infinite", "C", "Explanation: The dielectric reduces the electric field because the charge remains constant while the capacitance increases."),
                ("PHY102", "Capacitance & Current Electricity", "The capacitance of a parallel-plate capacitor can be increased by", "Increasing the distance between the plates", "Reducing the plate area", "Using a dielectric with higher permittivity", "Reducing the dielectric constant", "C", "Explanation: A material with higher permittivity increases the capacitance."),
                ("PHY102", "Current Electricity", "Which quantity is directly responsible for establishing current in a conductor?", "Charge only", "Potential difference", "Capacitance", "Electric flux", "B", "Explanation: A potential difference creates the electric field that drives charge through the conductor."),
                ("PHY102", "Capacitance & Current Electricity", "A 5 μF capacitor stores 0.001 C of charge. The potential difference across it is", "50 V", "100 V", "200 V", "500 V", "C", "Explanation: V = Q/C = 0.001 ÷ (5 × 10⁻⁶) = 200 V."),

                ("PHY102", "Capacitance & Current Electricity", "Two identical capacitors are connected in series across a battery. If one capacitor suddenly develops a leakage path, the charge on the other capacitor will", "Increase", "Decrease with time", "Remain unchanged", "Become infinite", "B", "Explanation: A leakage path allows the stored charge in the series circuit to discharge, reducing the charge on both capacitors."),
                ("PHY102", "Capacitance", "A capacitor is connected to a battery and charged. The battery is then disconnected before the plate area is doubled. The final potential difference across the capacitor becomes", "Twice its original value", "Half its original value", "Unchanged", "Four times its original value", "B", "Explanation: After disconnecting the battery, charge remains constant. Doubling the plate area doubles the capacitance, so the voltage becomes half."),
                ("PHY102", "Capacitance", "A dielectric slab completely fills the space between the plates of an isolated charged capacitor. Which quantity decreases?", "Charge", "Capacitance", "Electric field", "Plate area", "C", "Explanation: For an isolated capacitor, charge remains constant while the dielectric reduces the electric field and potential difference."),
                ("PHY102", "Capacitance", "Three capacitors of 2 μF, 3 μF, and 6 μF are connected in series. The equivalent capacitance is", "1 μF", "11 μF", "6 μF", "2 μF", "A", "Explanation: 1/C = 1/2 + 1/3 + 1/6 = 1, so Ceq = 1 μF."),
                ("PHY102", "Capacitance", "Which capacitor stores the LEAST energy when identical capacitors are connected in series?", "The first capacitor", "The last capacitor", "They all store the same energy", "The capacitor nearest the battery", "C", "Explanation: In series, identical capacitors have equal charge and equal voltage, so each stores the same energy."),
                ("PHY102", "Capacitance", "If the capacitance of a capacitor is tripled while the stored charge remains constant, the stored energy becomes", "Three times larger", "One-third of its original value", "Nine times larger", "Unchanged", "B", "Explanation: U = Q²/(2C). Increasing C by 3 reduces the energy to one-third."),
                ("PHY102", "Capacitance", "The equivalent capacitance of capacitors connected in series is always", "Greater than the largest capacitor", "Equal to the smallest capacitor", "Less than the smallest capacitor", "Equal to the average capacitance", "C", "Explanation: Series combination always produces an equivalent capacitance smaller than the smallest individual capacitor."),
                ("PHY102", "Capacitance", "Two capacitors have capacitances C and 2C. Connected in series, the ratio of their potential differences is", "1 : 2", "2 : 1", "1 : 1", "4 : 1", "B", "Explanation: Series capacitors carry equal charge. Since V = Q/C, voltage is inversely proportional to capacitance."),
                ("PHY102", "Capacitance", "Which statement about the electric field inside the dielectric of a capacitor is correct?", "It is always greater than in vacuum.", "It becomes zero.", "It is reduced compared with vacuum.", "It reverses direction.", "C", "Explanation: Polarization of the dielectric weakens the internal electric field."),
                ("PHY102", "Capacitance", "A capacitor is connected to a battery. If both the plate area and plate separation are doubled simultaneously, the capacitance becomes", "Twice the original", "Half the original", "Unchanged", "Four times the original", "C", "Explanation: Since C = εA/d, doubling both A and d leaves C unchanged."),
                ("PHY102", "Current Electricity", "Two wires of the same material have equal lengths, but one has twice the cross-sectional area of the other. If connected to the same voltage source, the larger wire carries", "The same current", "Twice the current", "Half the current", "Four times the current", "B", "Explanation: Resistance is inversely proportional to area. Doubling the area halves the resistance, doubling the current."),
                ("PHY102", "Current Electricity", "Which statement correctly distinguishes drift velocity from random molecular motion?", "Both are in the same direction.", "Random motion causes electric current.", "Drift velocity is the net average motion caused by an electric field.", "Drift velocity is always greater than random speed.", "C", "Explanation: Random motion produces no net current, while drift velocity results from an applied electric field."),
                ("PHY102", "Current Electricity", "A conductor carries 3.2 × 10⁻¹⁹ C through a cross-section in 0.20 s. The current is", "0.16 A", "1.6 × 10⁻¹⁸ A", "3.2 × 10⁻¹⁸ A", "6.4 × 10⁻¹⁹ A", "B", "Explanation: I = Q/t = (3.2 × 10⁻¹⁹)/(0.20) = 1.6 × 10⁻¹⁸ A."),
                ("PHY102", "Current Electricity", "A battery delivers a constant current to a conductor. If the time is doubled, the total charge delivered becomes", "Half", "Twice", "Four times", "Unchanged", "B", "Explanation: Since Q = It, doubling time doubles the total charge."),
                ("PHY102", "Current Electricity", "Which of the following quantities is NOT affected by reversing the direction of conventional current?", "Magnitude of current", "Direction of electron drift", "Electric field direction", "Direction of charge flow", "A", "Explanation: Only the direction changes. The magnitude of the current remains the same."),
                ("PHY102", "Current Electricity", "A capacitor connected to a DC source initially behaves most like", "An open switch", "A resistor of infinite resistance", "A short circuit", "A battery", "C", "Explanation: Immediately after connection, an uncharged capacitor allows maximum current, behaving like a short circuit."),
                ("PHY102", "Capacitance", "Which of the following increases the energy stored in an isolated charged capacitor?", "Increasing the capacitance", "Inserting a dielectric", "Reducing the capacitance", "Increasing the plate area", "C", "Explanation: For constant charge, U = Q²/(2C). Reducing capacitance increases stored energy."),
                ("PHY102", "Capacitance", "A parallel-plate capacitor is completely filled with a dielectric of relative permittivity 5. Its capacitance becomes", "C/5", "5C", "25C", "√5 C", "B", "Explanation: A dielectric increases capacitance by its dielectric constant."),
                ("PHY102", "Current Electricity", "If 6.25 × 10¹⁸ electrons pass through a wire every second, the current in the wire is approximately", "0.5 A", "1 A", "2 A", "5 A", "B", "Explanation: I = ne = (6.25 × 10¹⁸)(1.6 × 10⁻¹⁹) = 1 A."),
                ("PHY102", "Capacitance & Current Electricity", "A student claims that increasing the voltage across a capacitor always increases its capacitance. The statement is", "Correct for all capacitors", "Correct only for parallel capacitors", "False because capacitance depends on geometry and dielectric, not voltage", "True only when a dielectric is present", "C", "Explanation: Capacitance is determined by the physical dimensions and dielectric material, not by the applied voltage."),
                
                ("PHY102", "Current Electricity", "A wire carries a current I. If both the charge of each carrier and the number of charge carriers passing a cross-section per second are doubled, the new current is", "I", "2I", "3I", "4I", "D", "Explanation: Current I = nq. Doubling both the number of carriers and their charge makes the current four times its original value."),
                ("PHY102", "Current Electricity", "The drift velocity of electrons in a metallic conductor is directly proportional to the", "Resistivity of the conductor", "Applied electric field", "Length of the conductor only", "Cross-sectional area only", "B", "Explanation: Drift velocity increases linearly with the applied electric field."),
                ("PHY102", "Current Electricity", "Current density is defined as", "Current per unit resistance", "Current per unit cross-sectional area", "Charge per unit volume", "Power per unit area", "B", "Explanation: Current density J = I/A and is measured in A/m²."),
                ("PHY102", "Current Electricity", "A wire carries 8 A of current. If its cross-sectional area is doubled while the current remains unchanged, the current density becomes", "Twice its original value", "Half its original value", "Four times its original value", "Unchanged", "B", "Explanation: Since J = I/A, doubling the area halves the current density."),
                ("PHY102", "Current Electricity", "Which statement correctly describes an ohmic conductor?", "Its resistance increases with increasing current.", "It obeys Ohm's law only at high temperatures.", "Its current is directly proportional to the applied voltage at constant temperature.", "Its resistance is always zero.", "C", "Explanation: Ohmic conductors obey Ohm's law provided the temperature remains constant."),
                ("PHY102", "Current Electricity", "A resistor has a resistance of 12 Ω. If the voltage across it is doubled, its resistance becomes", "6 Ω", "12 Ω", "24 Ω", "48 Ω", "B", "Explanation: Resistance is a property of the material and dimensions, not of the applied voltage."),
                ("PHY102", "Current Electricity", "The SI unit of resistivity is", "Ω", "Ω/m", "Ω·m", "S/m", "C", "Explanation: Resistivity is measured in ohm metre (Ω·m)." ),
                ("PHY102", "Current Electricity", "Which material generally has the highest electrical conductivity?", "Rubber", "Copper", "Glass", "Wood", "B", "Explanation: Copper has very low resistivity and therefore high conductivity."),
                ("PHY102", "Current Electricity", "The resistance of a metallic conductor generally increases with temperature because", "The number of free electrons decreases drastically.", "Collisions between electrons and atoms become more frequent.", "The wire becomes positively charged.", "Its cross-sectional area becomes zero.", "B", "Explanation: Increased lattice vibrations cause more frequent collisions, increasing resistance."),
                ("PHY102", "Current Electricity", "Which material has a negative temperature coefficient of resistance?", "Copper", "Aluminium", "Carbon", "Silver", "C", "Explanation: Carbon and semiconductors generally have negative temperature coefficients."),
                ("PHY102", "Current Electricity", "The electromotive force (EMF) of a battery is best defined as", "The force exerted on electrons.", "The terminal voltage under load.", "The energy supplied per unit charge by the source.", "The current produced by the battery.", "C", "Explanation: EMF is the work done or energy supplied by the source per unit charge."),
                ("PHY102", "Current Electricity", "A battery has an EMF of 12 V and an internal resistance of 1 Ω. If it supplies a current of 2 A, the terminal voltage is", "10 V", "12 V", "14 V", "16 V", "A", "Explanation: Terminal voltage V = E - Ir = 12 - (2 × 1) = 10 V."),
                ("PHY102", "Current Electricity", "The terminal voltage of a battery equals its EMF when", "The battery is supplying maximum current.", "The internal resistance is infinite.", "No current flows through the battery.", "The external resistance is zero.", "C", "Explanation: When I = 0, there is no voltage drop across the internal resistance, so terminal voltage equals EMF."),
                ("PHY102", "Current Electricity", "A battery is short-circuited. The current is limited mainly by its", "EMF only", "External resistance", "Internal resistance", "Power rating", "C", "Explanation: In a short circuit, the external resistance is nearly zero, so the internal resistance limits the current."),
                ("PHY102", "Current Electricity", "An electric heater is rated 2000 W at 250 V. Its operating current is", "4 A", "6 A", "8 A", "10 A", "C", "Explanation: I = P/V = 2000/250 = 8 A."),
                ("PHY102", "Current Electricity", "A 100 W bulb operates for 5 hours. The electrical energy consumed is", "0.5 kWh", "5 kWh", "50 kWh", "500 Wh", "A", "Explanation: Energy = Power × Time = 100 W × 5 h = 500 Wh = 0.5 kWh."),
                ("PHY102", "Current Electricity", "According to Joule's law of heating, the heat produced in a resistor is proportional to", "I²Rt", "IR²t", "V²/R²", "I/R", "A", "Explanation: Joule's law states that H = I²Rt."),
                ("PHY102", "Current Electricity", "Two resistors of equal resistance are connected separately across the same battery. Which resistor produces more heat in the same time?", "The first resistor", "The second resistor", "Both produce equal heat", "Cannot be determined", "C", "Explanation: Equal resistances connected to the same voltage dissipate equal power and produce equal heat."),
                ("PHY102", "Current Electricity", "A copper wire is stretched to twice its original length without changing its volume. The new resistance is", "R", "2R", "3R", "4R", "D", "Explanation: Since volume is constant, doubling the length halves the area. R = ρL/A, so R becomes four times its original value."),
                ("PHY102", "Current Electricity", "Which of the following statements is FALSE?", "Current density is a vector quantity.", "Drift velocity and conventional current have the same direction in a metal.", "Conductivity is the reciprocal of resistivity.", "Power dissipated in a resistor can be expressed as I²R.", "B", "Explanation: In metals, electrons drift opposite to the direction of conventional current."),

                ("PHY102", "Current Electricity", "A wire of resistance R is cut into three equal parts. One part has a resistance of", "R/9", "R/6", "R/3", "3R", "C", "Explanation: Resistance is directly proportional to length. Reducing the length to one-third reduces the resistance to R/3."),
                ("PHY102", "Current Electricity", "Two wires are made of the same material and have the same length. If one wire has twice the diameter of the other, its resistance is", "Twice as large", "Half as large", "One-fourth as large", "Four times as large", "C", "Explanation: Since R ∝ 1/A and A ∝ d², doubling the diameter increases the area fourfold, reducing the resistance to one-fourth."),
                ("PHY102", "Current Electricity", "The drift velocity of electrons is very small, yet electric devices operate almost instantly because", "Electrons move at the speed of light.", "The electric field propagates rapidly through the conductor.", "Current is carried by protons.", "The battery stores electrons at the appliance.", "B", "Explanation: Although electrons drift slowly, the electric field establishing the current propagates through the circuit nearly at the speed of light."),
                ("PHY102", "Current Electricity", "A wire carries a steady current. Which quantity is the same at every cross-section of the wire?", "Current density", "Drift velocity", "Current", "Electric field", "C", "Explanation: Charge conservation requires the same current through every cross-section of a conductor in steady state."),
                ("PHY102", "Current Electricity", "Current density in a conductor is zero when", "The conductor is neutral.", "Electrons are completely absent.", "There is no net drift of charge carriers.", "The temperature is zero kelvin.", "C", "Explanation: Random motion exists, but current density becomes zero when there is no net drift velocity."),
                ("PHY102", "Current Electricity", "Which of the following will NOT change the resistance of a metallic wire?", "Changing its length", "Changing its cross-sectional area", "Changing its temperature", "Changing the applied voltage while temperature remains constant", "D", "Explanation: For an ohmic conductor at constant temperature, resistance is independent of the applied voltage."),
